quests[11275] = { id = 11275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making the Horn", description = "My people have been hunting the giant yeti of these hills for generations and I will be participating for the first time this year. It will probably be the last before we leave the post forever.\n\nTo prepare for the hunt, I must fashion a loud horn from the horns of the dire rams that roam the snowy areas near our camp. The elders tell me the sound mimics the mating call of the female yeti, but I have my doubts.\n\nBring me the best dire ram horns you can find, {name}, and I'll select one from among them.", sourceObjective = "Nokoma Snowseer at Camp Winterhoof wants you to bring her 6 Undamaged Ram Horns.", progress = "Have you brought any suitable horns?", completion = "These are all fine horns, {name}. Let me examine them and select the one I will use in the hunt.\n\nI'll give the rest to the craftsmen for use in their carvings.", sourceObjectiveStatus = "unverified-source-field" }
quests[11276] = { id = 11276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And Then There Were Two...", description = "There's no sign of the cipher on Zedd. After carefully searching the area you discover some writing in the dirt:\n\n\"Glor and Dae inside catacombs. Have cipher and tablets.\"\n\nPerhaps you should head into the catacombs located just north of here and search for Glorenfeld and Daegarn. The bridge crossing the worg pit will lead you right to the tunnel leading down into the catacombs.", sourceObjective = "Search the Utgarde Catacombs for Glorenfeld.", completion = "About bloody time! Pulroy and Zedd are dead.\n\nAnd Daegarn...\n\n<Glorenfeld shakes his head.>\n\nTaken by the Dragonflayer chieftain into the depths of these catacombs. I overheard that oversized mongrel mention something 'bout a sacrifice to the \"Dread King.\"\n\nThe cipher is hidden away in Daegarn's grimy beard.\n\nWhat? Dwarves hide things in their beards all the time!", sourceObjectiveStatus = "unverified-source-field" }
quests[11277] = { id = 11277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Depths of Depravity", description = "They're keepin' Daegarn locked up in a cage at the large fightin' ring nearby. From what I've gathered, the Dragonflayers bring out their prisoners to battle against their most powerful gladiators. They dump the losers in the basement where Scourge necromancers turn 'em into ghoulies! It's horrifying!\n\nBut first things first! The tablets are strewn about all across this dungeon. Let's get those recovered before you go off tryin' to be a hero.", sourceObjective = "Glorenfeld at the Utgarde Catacombs wants you to collect 10 Wyrmskull Tablets.", progress = "Check every nook and cranny!", completion = "You've done well, mate. Now that we've secured the tablets we can try and save Daegarn's life and recover the cipher that will help us decode the meaning behind these ancient relics!\n\nI'll hold on to these tablets, you rescue Daegarn.", sourceObjectiveStatus = "unverified-source-field" }
quests[11278] = { id = 11278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Valgarde", description = "'Tis a shame we lost two of our best dwarves while uncovering these relics. They sacrificed their lives to keep this information safe.\n\n<Glorenfeld wraps the cipher and tablets in a tattered cloth.>\n\nTake these back to Valgarde. McSorf will know what to do with the find.\n\nAs for me? I'll be alright on my own. I've gotten this far in one piece!", sourceObjective = "Take Glorenfeld's Package to Beltrand McSorf at Valgarde Port.", progress = "You're back!", completion = "Sorting these tablets out is going to take some time. All I can gather from a precursory study is that whatever used to be here was an ancestor of the humans. Those vrykul things probably killed 'em all off. Anyhow, we'll know more once I get these relics set up.", sourceObjectiveStatus = "unverified-source-field" }
quests[11279] = { id = 11279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Green Eggs and Whelps", description = "This new plague that we're working on is wonderful and I think we should expand its testing.\n\nHow about testing it on proto-whelps?!\n\nJust think of the possibilities. The ability to infect not only humanoids, but extend our reach to any creature!\n\nHere, I've hoarded an extra plague canister for the right time and place, and you look like the right person.\n\nSpray the eggs at Ember Clutch to the northwest, then get specimens from the plagued proto-whelps that hatch.", sourceObjective = "Plaguebringer Tillinghast has asked you to collect 10 Plagued Proto-Whelp Specimens and deliver them to him at New Agamand.", progress = "Without those samples, how am I to tell if this latest strain of the plague can be expanded for use on all sorts of creatures?", completion = "What?! No, this can't be right.\n\nCURSES!\n\nThis batch of the plague doesn't seem to have had any real effect on the proto-whelps at all other than to make them glow green!\n\nMy dream of using the plague upon anything we come into contact with seems to have gone up in smoke!", sourceObjectiveStatus = "unverified-source-field" }
quests[11280] = { id = 11280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draconis Gastritis", description = "Wait, that gives me an idea! What if it didn't kill the whelps because it was sprayed on the outside of their eggs?\n\n{name}, we have to get the plague inside of them!\n\nI know! I've got some plagued meat here. Take it to the Ember Clutch and get them to eat it!\n\nBut no, we're thinking too small. Let's get one of the proto-drakes flying overhead to come down and eat it.\n\nYes!\n\nStay close to the meat and observe what happens. Yes, it might attack you, but such is the price of progress.", sourceObjective = "Plaguebringer Tillinghast at New Agamand wants you to use Tillinghast's Plagued Meat to attract down a Proto-Drake and observe its reaction to eating the stuff.", completion = "NOOOOOOOOOOOOOOOO!!!\n\n<The plaguebringer begins to cry.>\n\nAll of my hopes... all of my dreams, ruined!\n\nLeave me, {name}. Leave me to my despair. I'm nothing.\n\nHere, you might as well take all of my worldly possessions. When the rest of the apothecaries hear of my failure, I'll be done for and won't need them anyway.", sourceObjectiveStatus = "unverified-source-field" }
quests[11281] = { id = 11281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mimicking Nature's Call", description = "The horn has been roughed out, but before I make the traditional carvings, I want to be certain that it will work. Ahota tells me that he tests his horns at the foot of the frozen waterfall to the northeast of the post. Ahota tells me that our hunters have used the acoustics of frozen water in this way for generations. I can't wait to learn more!\n\nWill you help me test out the horn? If I've done everything right, you may even attract a yeti, so be prepared! Bring the horn back once you've tested it.", sourceObjective = "Test the Carved Horn and then return to Nokoma Snowseer at Camp Winterhoof with the results.", completion = "<Nokoma listens to your report from the test.>\n\nI'm relieved that the horn worked so well... maybe too well if what you're saying was true. You're sure the beast spoke? I don't know if I can go on with the hunt if that's true. I'll have to speak with Chief Ashtotem about it.\n\nThis horn may end up being merely decorative, but that won't diminish its worth. Thank you for all your help, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11282] = { id = 11282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson in Fear", description = "When you've been in lots of fight like Gorth, you learn that to beat enemy good you have to make them really scared to die!\n\nBut these vrykuls not afraid.  You kill one and another comes... screaming louder and with a bigger weapon than the one before.\n\nOnly thing that makes vrykuls afraid is when we kill the biggest and baddest vrykul of all.\n\nGo fight the Winterskorn across the blockade until hero vrykuls show up!  Then you kill them dead and put queen's flag on corpses.  They must learn to fear!", sourceObjective = "Gorth wants you to kill Ulf the Bloodletter, Oric the Baleful and Gunnar Thorvardsson and drive the Forsaken Banner through their corpses. Slay Vrykul across the Forsaken blockade until they appear.", progress = "You kill them vrykuls?  They sure is tough!", completion = "You do some good killings over there.  I see vrykul men fall and get stabbed with Sylvanas flag.  Our side doing good!", sourceObjectiveStatus = "unverified-source-field" }
quests[11283] = { id = 11283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baleheim Bodycount", description = "Them vrykuls just keeps coming and coming out from town west of here.  No end in sight!\n\nGorth has an idea.  You go INSIDE town and kill them Winterskorn there.  THEN they stop coming here!", sourceObjective = "Sergeant Gorth wants you to kill 16 Winterskorn Vrykul inside Baleheim.", progress = "You done with the killings yet?  Winterskorn town right across from here!", completion = "You must have lots of practice with doing killings.  You almost as good as Gorth!", sourceObjectiveStatus = "unverified-source-field" }
quests[11284] = { id = 11284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Yeti Next Door", description = "Maybe if the sentries won't help me, you will? I'm the foreman of the mine just across the bridge. My men are mining ore for the weapons our expeditionary force will need to carve a path into the Grizzly Hills.\n\nA giant yeti has invaded the mine, blocking the tunnel we need to expand! We've tried yelling at him and smoking him out, but nothing's worked.\n\nMaybe you could rouse it from its sleep with a meal of meat from the frosthorn rams in the snowy areas around town? Please? We're desperate!", sourceObjective = "Foreman Colbey at Fort Wildervar wants you to defeat Shatterhorn.", progress = "Have you had any luck removing that stupid yeti from my mine?", completion = "You've done it? By the Light, you're a walking miracle! I was beginning to think I'd personally have to explain to Captain Adams why his men's weapons weren't ready in time!", sourceObjectiveStatus = "unverified-source-field" }
quests[11285] = { id = 11285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baleheim Must Burn!", description = "Killing the Winterskorns maybe not enough.  Maybe we burn their houses too!  Uh... and their bridges.  We should burn whole town to be safe!\n\nYou take this torch.  Go to Baleheim, to the west, and burn EVERYTHING!  That teach them good.", sourceObjective = "Sergeant Gorth wants you to go to Baleheim and use Gorth's Torch to burn 1 Winterskorn Dwelling, 1 Winterskorn Watchtower, 1 Winterskorn Bridge and 1 Winterskorn Barracks.", progress = "You done burning everything?  Make sure you not leave something not burned.", completion = "I guess you burned everything.  I see couple of spots not burning... but is close enough for Gorth.", sourceObjectiveStatus = "unverified-source-field" }
quests[11286] = { id = 11286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Artifacts of Steel Gate", description = "I came out here for a different reason; an old friend of mine has been calling to me in my dreams. But now that I see these small things with their machines making a big hole in the ground, it makes my blood boil.\n\nFrom what I can see, these dwarves, as they are known, are digging up artifacts; artifacts that could be important to our past.\n\nI want you to go down there and get these things for me. Don't let any of those dwarves stand in your way.", sourceObjective = "Sage Mistwalker has asked you to collect 10 Steel Gate Artifacts. When you have all of them, return to him at Steel Gate.", progress = "How many artifacts have you managed to gather from this Steel Gate?", completion = "<The sage grunts his approval at your actions on his behalf.>\n\nPerhaps I will be able to find the time soon to study these artifacts and come to an understanding of their significance.\n\nBut now there are more pressing matters to attend to.", sourceObjectiveStatus = "unverified-source-field" }
quests[11287] = { id = 11287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Sage Mistwalker", description = "{class}, I grow worried that my son, Sage Mistwalker, has been gone for such a long time. The land is cruel and deadly.\n\nHe spoke of a recurring vision that he had of a wolf, and went west with a small group of longrunners to seek its source. I believe the name of the place he mentioned was Steel Gate.\n\nWill you find him? I want to make sure that no ill has befallen him.", sourceObjective = "Greatmother Ankha has asked you to check on the condition of Sage Mistwalker. She believes him to be at or near Steel Gate.", completion = "My mother should not concern herself with my safety. But, I thank you for coming, stranger.\n\nSince you are here, perhaps you will help me with a few things?", sourceObjectiveStatus = "unverified-source-field" }
quests[11288] = { id = 11288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shining Light", description = "<Ares gasps for air as he tries to speak.>\n\nI am an envoy of the Argent Crusade, charged with a sacred duty.\n\nOur forces were decimated in the Plaguelands. By the light of dawn, the artifact was cleansed and made pure once more. So many perished in the wake of its redemption.\n\nThere is still a chance... still time.\n\nThe artifact was hurled into the den of the fallen, far below us. Guarded by the unmerciful dead.\n\n<Ares' body glows with blinding light.>\n\nLight. Will. Protect. You.", sourceObjective = "Ares the Oathbound in the Utgarde Catacombs wants you to recover the Sacred Artifact.\n\nThis is a timed quest.", progress = "<Ares is unconscious.>", completion = "You feel compelled to place the sacred blade next to the body of Ares.\n\nUpon doing this you are once again blinded by light.", sourceObjectiveStatus = "unverified-source-field" }
quests[11289] = { id = 11289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guided by Honor", description = "<Ares smiles.>\n\nGlory to the Light. You have done it!\n\n<Ares coughs.>\n\nTake the artifact and return it to Valgarde. Lord Irulon Trueblade awaits its return.\n\nFight with honor, friend. Always. Honor.\n\n<Ares dies.>", sourceObjective = "Return the Sacred Artifact to Lord Irulon Trueblade at Valgarde.", progress = "By the Light!", completion = "Many men and women died to recover this blade. Alas, I fear valiant Ares will not be the last.\n\nBut you do the Light's work, hero. This sacred blade will be wielded by Lord Tirion Fordring himself. Even now the Argent Crusade works toward Icecrown. Lord Fordring has vowed that he will tear down the walls of the cursed place himself! And with the blade, he just might stand a chance against the Lich King.\n\nLord Fordring remains our greatest hope.", sourceObjectiveStatus = "unverified-source-field" }
quests[11290] = { id = 11290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonflayer Battle Plans", description = "While we were able to gather very little information as to the whereabouts of Ingvar, we do know that Yanis resides in a cave next to the worg pit inside Wyrmskull Village.\n\nIntelligence gathered from the rescued soldiers indicates that Yanis guards Dragonflayer battle plans.\n\nI need you to go back to Wyrmskull and recover those plans. Kill any vrykul that get in your way - including Yanis!", sourceObjective = "Vice Admiral Keller at Valgarde Port in the Howling Fjord has asked that you bring him the Dragonflayer Battle Plans.", progress = "Have you recovered the Dragonflayer battle plans?", completion = "<Vice Admiral Keller glances over the plans.>\n\nOutstanding! By the looks of things, there are many more vrykul villages in the fjord. A different tribe of vrykul is preparing an assault on Westguard Keep. Hell, for all I know it may already be too late. We haven't heard from Westguard in days. Either way, we must alert Westguard!", sourceObjectiveStatus = "unverified-source-field" }
quests[11291] = { id = 11291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Westguard Keep!", description = "<Vice Admiral Keller rolls up the battle plans.>\n\nWe've got all the information we need to keep Valgarde protected. You must take these battle plans to Westguard Keep, located on the western fjord cliff wall. Speak with the flight master assistant, Emilune Winterwind. She will put you on the back of a gryphon headed towards Westguard.\n\nOnce there, find Captain Adams. He's the one in charge. Adams will know what to do with these plans.", sourceObjective = "Take the Dragonflayer Battle Plans to Captain Adams at Westguard Keep in the Howling Fjord.", progress = "Valgarde has not fallen? That's a surprise.\n\nMust be due to your help. It sure wasn't because of Keller.", completion = "<Captain Adams takes the plans from you.>\n\nI'm glad you decided to come over. My advisors and I will need some time to study these plans. In the meantime, we can use all the help we can get!", sourceObjectiveStatus = "unverified-source-field" }
quests[11292] = { id = 11292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preying Upon the Weak", description = "Glad to meet you. I've come here from the Grizzly Hills to do business with your cohorts. My people maintain a large outpost there, and you'd do well to visit it when you head north.\n\nI've set up traps in the woodlands and snowy areas around here. With the meat and the furs from the creatures they capture, I'll have plenty to barter with the townspeople.\n\nI can offer you a share of my profits if you're willing to help gather prey from the traps. Beware though, you won't be the only predator out there.", sourceObjective = "Trapper Jethan at Fort Wildervar wants you to bring him 8 pieces of Trapped Prey.", progress = "I hope you haven't returned empty-handed. I thought we had a deal.", completion = "<Trapper Jethan inspects the creatures you've brought him.>\n\nNicely done. Some of these will fetch a better price than others, but I should have plenty to trade with the locals.", sourceObjectiveStatus = "unverified-source-field" }
quests[11293] = { id = 11293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bark for the Barleybrews!", description = "We need to get the word out about the Barleybrews at Brewfest.  You need to shout at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.  I'll make things easy though, I'll lend you some racing ram reins and a racing ram for 4 minutes.  Use the reins to let him go, but try not to tire him out.", sourceObjective = "Spread the word about Brewfest at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.", progress = "Have you finished spreading the word about Brewfest?  But more importantly, did you let people know about the Barleybrews?", completion = "Well done!  That kinda shouting is sure to bring business our way.\n\nAnd we promised you a reward, here it is.  The Barleybrews keep their word.\n\nOh, and come back any other day if you want to help spread the good name of Barleybrew.", sourceObjectiveStatus = "unverified-source-field" }
quests[11294] = { id = 11294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bark for the Thunderbrews!", description = "It's time to let people know that the Thunderbrew have heard their cries for good brew.  You need to shout at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.\n\nWe'll make it easy though.  We'll lend you a ram AND some reins for 4 minutes.\n\nBe careful with going too fast though since you won't find any apple crates in Ironforge...  We can't take the chance of helping out the Barleybrew messengers.", sourceObjective = "Spread the word about Brewfest at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.", progress = "Did you let everyone know that the Thunderbrews are here at Brewfest?", completion = "Good job!  That'll show those arrogant Barleybrews.\n\nWell we promised you a reward and here it is.  We Thunderbrew reward you with prizes, the Barleybrew reward you with foul odors and false promises.\n\nYou chose wisely.\n\nIf you want to keep making the right choice, stop by another day and help us spread the word.", sourceObjectiveStatus = "unverified-source-field" }
quests[11295] = { id = 11295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Offensive Begins", description = "No one seems to know very much about the vrykul.  Our records show no signs of activity in their lands for centuries.  Yet here they are, just as we move against Arthas.\n\nThe map you retrieved makes it clear that we'll have to defeat them if our forces are to get any further into Northrend.\n\nOne of my best sergeants, an abomination known as Gorth, oversees the blockade beyond the lift.  Assist him in launching a pre-emptive strike on Baleheim.  If a vrykul attack occurs, it will be launched from there.", sourceObjective = "Speak to Sergeant Gorth at the blockade near the elevator west of Vengeance Landing in Howling Fjord.", completion = "You come to help?  Good... good...\n\nGorth was getting tired of killing vrykuls all day.  Help is welcome!", sourceObjectiveStatus = "unverified-source-field" }
quests[11296] = { id = 11296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rivenwood Captives", description = "Something, most likely the walking dead known as the Scourge, has agitated the creatures hereabouts.\n\nWhile escorting the sage here, we lost most of our hunting force to the riven widows -- huge and deadly spiders, which inhabit the Rivenwood to the north.\n\nI must stay here to protect the small force we have left, but you... you could see if my longrunners are still alive, trapped within the riven widow's cocoons.\n\nWould you do this, stranger?", sourceObjective = "Longrunner Skycloud has asked you to free his 7 Winterhoof Longrunners. Once you have managed to do so, return to him at Steel Gate.", progress = "I hold out hope that my hunting force is still alive.\n\nThe sting of the widows is slow to be fatal. They like to keep their victims alive long enough that their babies will be able to gorge themselves when they hatch.", completion = "That was a very brave act, {class}. I did not know that your people were capable of such selflessness.\n\nNext time I will heed the warnings of my elders and steer clear of the Rivenwood. I advise you to do the same.", sourceObjectiveStatus = "unverified-source-field" }
quests[11297] = { id = 11297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeping Watch on the Interlopers", description = "Even the earth cannot hold back the tide of death washing over it. Corpses walk the land, spreading their putrefaction with alarming speed.\n\nA small expedition has made its way up the western cliffs and rests near Whisper Gulch. Take a look for yourself, {name}. See if you can learn their purpose and dissuade them from bringing their poisons into our lands. Travel southwest from the post, toward the cliffs overlooking the western beach. Their camp will be west of the excavation at Steel Gate.", sourceObjective = "Speak to Apothecary Malthus at the Apothecary Camp.", completion = "Ah, yes, the reclusive bison-men of the north. I've seen them skulking about, believing themselves unseen. I suppose they fancy this land theirs? Well, that's but one of many things that will change shortly.\n\nI wasn't expecting any company, but while you're here on that fool's errand, you might as well make yourself useful.", sourceObjectiveStatus = "unverified-source-field" }
quests[11298] = { id = 11298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's in That Brew?", description = "To the southeast is an area called Whisper Gulch. It's overrun with members of the Explorers' League who've gone mad! They attacked our caravan as it passed through the area, and they've harried our foraging parties as well.\n\nI must know what's causing this madness! I suspect that whatever they're drinking from the kegs scattered around the gulch contributes to their insanity. I want you to steal the kegs from those dwarves while they're busy mining away.", sourceObjective = "Apothecary Malthus at the Apothecary Camp wants you to bring him 5 Dwarven Kegs.", progress = "Did you get those kegs or not?", completion = "<The apothecary pours out a tankard of the beverage for himself.>\n\nWell, here I go!", sourceObjectiveStatus = "unverified-source-field" }
quests[11299] = { id = 11299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ring of Judgement", description = "You might have already seen the room where Daegarn is being held while you were gatherin' the tablets. It's through this corridor and then down a set of steps. Daegarn will be in the room at the bottom of the steps - locked up tight!\n\nGet down there and find him. At the very least you might be able to get the cipher from him.", sourceObjective = "Find Daegarn in the Ring of Judgement located inside the Utgarde Catacombs.", completion = "Yep. You found me. Woopedy-do!\n\nAnd no, I don't have the cipher. My beard was the first thing those beasts checked! Oluf's the one that's got it now. He's the chieftain of the gladiators.", sourceObjectiveStatus = "unverified-source-field" }
quests[11300] = { id = 11300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stunning Defeat at the Ring", description = "Oluf will come out if you defeat the other gladiators. That's 'bout the only way we're getting' that cipher back. Put on your whompin' boots and get busy in the Ring of Judgement. If you do manage to get the cipher back, return it to Glorenfeld o'er near the entrance to these catacombs.\n\nMe? Don't worry about me! We're on the brink of discovering the missing link to human-kind!", sourceObjective = "Defeat the gladiators at the Ring of Judgement and face Oluf the Violent. Defeat Oluf and recover the Ancient Cipher.\n\nReturn the Ancient Cipher to Glorenfeld at the entrance to the Utgarde Catacombs.", progress = "Daegarn? The cipher?", completion = "Fascinating tale! Something is actually judgin' these things? To what end?! For what purpose?\n\nWell, never mind that nonsense. Someone else can figure out that stuff. We got the cipher and the tablets back - and only two fatalities in the whole ordeal.", sourceObjectiveStatus = "unverified-source-field" }
quests[11301] = { id = 11301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brains! Brains! Brains!", description = "Has Malthus drawn you in with his blather about beer kegs and crazy dwarves?\n\nI'm not questioning that the dwarves are crazy, but I don't think stealing their beer is going to do any good.\n\nWhat we need is brains. Lots of brains. We'll get down to the bottom of this mystery in no time, and perhaps even find a new component for the plague.\n\nTake this saw, go southeast into the Whisper Gulch, and kill yourself some dwarves. Use the saw to help you harvest the brains and bring them back here.", sourceObjective = "Apothecary Grick at the Apothecary Camp wants you to bring him 12 Deranged Explorer Brains.", progress = "Did you get those brains? If not, I want my saw back. You'd better not walk off with that saw.", completion = "These brains are beautiful! Gorgeous, even! They're exactly what I need.\n\nThank you for your help, {name}. Now I'll show Malthus the truth his beer goggles couldn't reveal.", sourceObjectiveStatus = "unverified-source-field" }
quests[11302] = { id = 11302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Enigmatic Frost Nymphs", description = "When we first scouted locations for the fort, we encountered hostile creatures at two of the glades here in the north. When we passed the snow-covered one directly south of the town, the dryads there watched us with interest, but did not attack.\n\nWe were tired and worn down by the weather. They could've easily killed several of our men, but they didn't.\n\nPerhaps, in reaching out to them, we might discover unexpected allies. Are you willing to travel to the Frozen Glade and make contact with them?", sourceObjective = "Speak with Lurielle at the Frozen Glade.", completion = "<Lurielle listens as you introduce yourself.>\n\nIt is good to finally meet you, {name}. We have long hoped that you and the other newcomers might send representatives. We don't often venture beyond the borders of our glades, especially amid the changes the land is going through.", sourceObjectiveStatus = "unverified-source-field" }
quests[11303] = { id = 11303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ambush", description = "The vrykuls in Baleheim is completely defeated, no doubt about it.  But still their leader stays in town and won't give up.\n\nGorth sends Lydell and his assassins to make good ambush to the northwest.  You talk to Lydell and figure out how to get Vrykul chieftain to come out.  Then you kill him.  You kill him real good.", sourceObjective = "Speak to Lydell at Lydell's Ambush.", completion = "We all showed up to the party, but the guest of honor stayed at home.", sourceObjectiveStatus = "unverified-source-field" }
quests[11304] = { id = 11304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Agamand", description = "I'm afraid our equipment isn't exactly the best here at Vengeance Landing.  After all it's a military controlled outpost.\n\nI will need you to take a sample of this strain to Chief Plaguebringer Harris in New Agamand, follow the road beyond Baleheim south and then west.  They have better equipment there - he will know what to do.\n\nYou must hurry, {name}.  Our enemies are stronger and more numerous than us.  We need to develop a viable weapon against them!", sourceObjective = "Bring Lysander's Strain to Chief Plaguebringer Harris in New Agamand in western Howling Fjord.", progress = "Yes, {name}?", completion = "This strain is far from worthless, my friend!  Those fools at Vengeance Landing have had all the answers right under their own noses!", sourceObjectiveStatus = "unverified-source-field" }
quests[11305] = { id = 11305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tailor-Made Formula", description = "We've been spraying down the vrykul village of Halgrind for weeks now and the vrykul just won't drop dead.\n\nLet's face it, {name}, by now our Plague has been exposed to humans, dwarves, dogs, livestock... you name it.  As our strains adapt to their hosts, more impurities get thrown in the mix.  What we need is a strain made custom for the vrykul's biology.\n\nHalgrind's chieftain fled the town after we took it over; you'll find him west of here.  As a patriarch of the Dragonflayer clan, his blood is ideal.", sourceObjective = "Obtain the Dragonflayer Patriarch's Blood from Thorvald at Thorvald's Camp and bring it to Chief Plaguebringer Harris in New Agamand.", progress = "Have you obtained the sample I require, {name}?", completion = "This will do.  It's time for some real apothecary work now, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11306] = { id = 11306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apply Heat and Stir", description = "You've done well so far, {name}.  I'd like to teach you some of my more advanced techniques, so that you gain a better understanding of the plague.\n\nTake this empty flask and fill it with blood from the cauldron to my left.  Mix it with the plague samples to my right until you obtain a well balanced mix.", sourceObjective = "Fill the Empty Apothecary's Flask at the Cauldron of Vrykul Blood, then mix the Flask of Vrykul Blood with Harris's Plague Samples nearby until you've obtained a Balanced Concoction.\n\nReturn to Chief Plaguebringer Harris when you've completed this task.", progress = "How is your experiment going, {name}?  Let me know if you have any questions behind the science involved!", completion = "Excellent!  You are an apt pupil, {name}.\n\nNow comes the fun part.  Deployment!", sourceObjectiveStatus = "unverified-source-field" }
quests[11307] = { id = 11307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Test", description = "Now that we have a strain of the plague that has adapted to vrykul carriers, we really ought to test it on our specimens in Halgrind.  If all goes according to plan, they will disintegrate immediately as the plague devours their innards!\n\nYou will find Halgrind north of here.  Our plaguebringers are deploying the previous strain there - shouldn't be hard to spot.", sourceObjective = "Venture into Halgrind and use the Plague Spray on 10 Plagued Dragonflayer Vrykul. Return to Chief Plaguebringer Harris to report the results.", progress = "Have you completed your field tests, {name}?", completion = "The plague didn't disintegrate our subjects?  Are you certain, {name}??!\n\nThere must be an external factor we're not accounting for... perhaps the low temperatures of this climate?  Perhaps... a mutation in the strain!", sourceObjectiveStatus = "unverified-source-field" }
quests[11308] = { id = 11308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time for Cleanup", description = "Being the practical man that I am, I'm going to declare our research here a success.  After all, what army can't be stopped by turning its rank and file against each other?\n\nI will send word of our achievements to Vengeance Landing soon enough.  But first I need you to take care of cleaning up our experimentation site.\n\nSee \"Hacksaw\" Jenny about making you a custom abomination.  One packing some explosive power if you catch my drift.", sourceObjective = "Speak to \"Hacksaw\" Jenny in New Agamand.", completion = "What do you want?  Can't you see I'm in the middle of something?", sourceObjectiveStatus = "unverified-source-field" }
quests[11309] = { id = 11309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parts for the Job", description = "So Harris wants a demolition job, eh?  Yeah, I can help out.\n\nYou're gonna have to get me some parts, though.  I can't afford to use up my choice components on something that's gonna get blown up.\n\nFirst of all, I'm going to need shoveltusk ligaments... way better than the human kind.\n\nI will also need a pound of flesh.  A fellow known as Anton sells cheap meat.  He travels up and down the road to the west.", sourceObjective = "\"Hacksaw\" Jenny in New Agamand wants you to obtain 6 Shoveltusk Ligaments and 1 Fresh Pound of Flesh.", progress = "You get my components yet?", completion = "Excellent!  Yes, yes, these will do just fine!", sourceObjectiveStatus = "unverified-source-field" }
quests[11310] = { id = 11310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warning: Some Assembly Required", description = "Well, here you are!  Our friend's going to be somewhat... unstable.  So I suggest not putting him together until reaching Halgrind.\n\nOnce you're there, use the abomination to round up as many vrykul as you can before self-destructing.\n\nCome back with whatever's left once you're done.  I can always use more body parts!", sourceObjective = "Use the Abomination Assembly Kit in Halgrind and round up plagued Vrykul with your Mindless Abomination. Slay at least 20 and return to \"Hacksaw\" Jenny in New Agamand when you're done.", completion = "Great job, {name}.  Say, you wouldn't be looking for something more... permanent, would ya?  I could sure use some help around these parts!", sourceObjectiveStatus = "unverified-source-field" }
quests[11311] = { id = 11311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suppressing the Elements", description = "If you are to survive here, as we have, you must learn to face the environment's challenges head on. The elements will claim your life if you're not vigilant, as the proliferation of elementals in these northern hills shows.\n\nWe must cull the elementals one last time before we can leave this place. Are you willing to aid us while we continue to make preparations?\n\nYou must kill any iceshard elementals or howling cyclones you encounter in the snowy hills surrounding the outpost.", sourceObjective = "Wind Tamer Kagan at Camp Winterhoof wants you to kill 8 mountain elementals. You may kill either Howling Cyclones or Iceshard Elementals.", completion = "The influence of the elemental spirits has receded, but it will return. We've bought ourselves the time we need to complete our tasks here and take our leave.", sourceObjectiveStatus = "unverified-source-field" }
quests[11312] = { id = 11312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Frozen Glade", description = "For generations, my people have told tales of frost nymphs cavorting in glades hidden away in the wilderness. I used to search for them as a child, against the advice of my parents, until I nearly froze to death.\n\nThese days, it isn't necessary to comb the forests for them. They've decided to reveal themselves for reasons I can only guess, but I don't think the change can be ignored. Venture southeast to the Frozen Glade and seek out the nymphs, but beware; you will pass the Twisted Glade on your way.", sourceObjective = "Speak with Lurielle at the Frozen Glade.", completion = "<Lurielle listens as you introduce yourself.>\n\nIt is good to meet you, {class}. My sisters have often watched the taunka search the forests for us, but we are forbidden by our queen from interacting with outsiders. You only see us now because the land has become unsettled and many of my sisters are in danger.", sourceObjectiveStatus = "unverified-source-field" }
quests[11313] = { id = 11313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits of the Ice", description = "The ice elementals surrounding our glade were once our companions, but a volatile and destructive force has swept through the land, turning them against us!\n\nThis is but one of the horrors my sisters and I have endured. We have revealed ourselves to you in the hope that you will help us stave off the decay that has crept into our glades and poisoned our sisters!\n\nWe've been gathering the cores of the ice elementals and keeping them safe so that one day, we might be able to restore them. Will you help?", sourceObjective = "Lurielle at the Frozen Glade wants you to bring her 15 Icy Cores.", progress = "Have you recovered any of the cores?", completion = "<Lurielle accepts the cores from you quietly.>\n\nThank you, {name}.\n\n\n\nI promise, my friends, I will do all I can to restore you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11314] = { id = 11314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fallen Sisters", description = "To the southwest was a glade that used to look much like this one. Mysterious forces and alien magics are reshaping the land. The glade has thawed, the sisters living there driven mad by the sudden change.\n\nWe thought to reach out to them, but they attacked us. I fear many may be beyond saving, but I cannot give up hope.\n\nTake my pendant, travel southwest to the Vibrant Glade, and use it to try to free my sisters.", sourceObjective = "Lurielle at the Frozen Glade wants you to use her pendant on 7 Chill Nymphs.", progress = "Were you able to heal any of my sisters using the pendant?", completion = "So there is hope for my sisters?\n\n<Lurielle looks away from you, then down at the ground.>\n\nI feel guilty for not thinking of the pendant sooner. We might have saved even more of the sisters.", sourceObjectiveStatus = "unverified-source-field" }
quests[11315] = { id = 11315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Vines", description = "The sisters who lived in the Vibrant Glade, to the southwest, used to tend to gorgeous beds of scarlet ivy, but the same force that has driven them mad has transformed their beloved ivy.\n\nThe vines now grasp at the feet of the unwary, or lash at any who approach the glade. Before we can reclaim the glade, the vines must be tamed and uprooted.\n\nClear as much of the ivy as you are able. It has already begun to grow out of control.", sourceObjective = "Lurielle at the Frozen Glade wants you to kill 8 Scarlet Ivy.", completion = "Thank you for your help, {name}. The Vibrant Glade was once a beautiful place, and when we return to it, we shall make it so again.", sourceObjectiveStatus = "unverified-source-field" }
quests[11316] = { id = 11316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spawn of the Twisted Glade", description = "The glade to the west has been transformed into a hideous place called the Twisted Glade. Horrible beasts dwell among the trees, stones, and pool of the glade.\n\nI cannot guess where the creatures came from or what horrible forces animate them, but they must be dealt with!\n\nI fear that if they are allowed to dominate the glade, they will poison it beyond redemption. Clear the glade of these creatures who murdered our sisters.", sourceObjective = "Lurielle at the Frozen Glade wants you to kill 10 Thornvine Creepers.", progress = "Have you seen the horrors of the Twisted Glade for yourself?", completion = "You have done well, {name}. If we'd had allies like you when the land first began to change, perhaps we might have been able to preserve some of what we've lost.", sourceObjectiveStatus = "unverified-source-field" }
quests[11317] = { id = 11317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cleansing", description = "We braved the Rivenwood because of my troubled dreams concerning my worg life-friend, Ulfang. He has called out for help, and you must go to him.\n\nBut, you do not have the means to speak with him, or walk amongst the other worgs. I know a way.\n\nFirst, you must cleanse your inner turmoil.\n\nThere is a shrine that sits at the top of Frostblade Peak, northeast of Camp Winterhoof. A single path leads up to it from the western base of the mountain.\n\nMeditate there and then return to me.", sourceObjective = "Sage Mistwalker at Steel Gate has advised you to cleanse yourself of Your Inner Turmoil through meditation at the Frostblade Shrine.", progress = "Did you find inner peace at the shrine? Is your turmoil gone?", completion = "Already I can sense the change within you.\n\nAre you ready for what comes next?", sourceObjectiveStatus = "unverified-source-field" }
quests[11318] = { id = 11318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Now This is Ram Racing... Almost.", description = "So you want to check out the racing rams?  Well I hope you're ready for speed.  BUT before I let you loose in the world, you'll need to show me that you can handle these fine creatures.\n\nSo here's the deal:  I'll lend you some racing reins and the use of a ram. You need to prove to me that you can handle using these rams.\n\nKeep the ram at a trot, canter and gallop for 8 seconds each.  If you need instructions how to handle the ram, talk to my apprentice, Pol Amberstill.", sourceObjective = "You have 4 minutes to ride the ram and maintain 3 different levels of speed for 8 seconds.", progress = "Were you able to handle the speed?", completion = "Nice work there!  It takes time to get the hang of controlling your ram.  But once you do, you'll wish every ram was a racing ram.\n\nWhat's that? \"Where's my reward?\"  Ha Ha Ha... you got to ride the fastest ram around!  You want more?  Well how about this...\n\nYou've been rewarded with the chance to help other people around Brewfest.  There's plenty of work, and rewards, for an eager, young, ram racer.", sourceObjectiveStatus = "unverified-source-field" }
quests[11319] = { id = 11319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeds of the Blacksouled Keepers", description = "The glade to the northwest, now the Twisted Glade, used to be home to a number of keepers of the glade. Together with the sisters, they saw to the glade's upkeep.\n\nWhen the glade changed, the sisters died, but somehow the keepers managed to survive. Now, they seed the land with poisonous spores that wither healthy greenery.\n\nI'll give you one of the cores from the ice elementals. Once you've destroyed a spore, use the ice crystal to freeze it and keep it from regenerating.", sourceObjective = "Lurielle at the Frozen Glade wants you to freeze 8 Spores.", progress = "The Twisted Glade is a terrible place. I never imagined our homes could become something so loathesome.", completion = "The ice core worked well for you? I'll have to remember that. I'm certain the keepers will not stop just because we've destroyed their work once.", sourceObjectiveStatus = "unverified-source-field" }
quests[11321] = { id = 11321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Did Someone Say \"Souvenir?\"", description = "Brewfest isn't just about racing rams, it's also about drinking!  When you have a moment, take this voucher to Belbi Quikswitch.  She's near the back of the Brewfest camp.  If you can't see her, don't worry, she'll be sure to see you.\n\nIn any case, take this voucher to her to get your free Brewfest stein.  She'll also be more than happy to handle any and all other Brewfest transactions.", sourceObjective = "Redeem the Brewfest Stein Voucher with Belbi Quikswitch in the Brewfest camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[11322] = { id = 11322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cleansing", description = "Of late I've had nightmares concerning a worg named Ulfang. He has called out for help, and you must go to him.\n\nHowever, you do not have the means to speak with him, or walk amongst the other worgs. I know a way.\n\nBut first, you must cleanse your inner turmoil through meditation.\n\nThere is a shrine that sits at the top of Frostblade Peak, far to the northeast. A single path leads up to it from the western base of the mountain.\n\nMeditate there to cleanse yourself and then return to me.", sourceObjective = "Watcher Moonleaf at Steel Gate has advised you to cleanse yourself of Your Inner Turmoil through meditation at the Frostblade Shrine.", progress = "Did you find inner peace at the shrine? Is your turmoil gone?", completion = "Already I can sense the change within you.\n\nAre you ready for what comes next?", sourceObjectiveStatus = "unverified-source-field" }
quests[11323] = { id = 11323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Worg's Clothing", description = "From my dreams, I know that Ulfang is in a cave on the snowy northwestern edge of the Rivenwood.\n\nHe is in great danger.\n\nI have devised a magical disguise that will make you appear as a worg while you are within the Rivenwood. The disguise is weak, relying upon the strange magics of that haunted wood. While it will only convince the worgs, it will allow you to get close to Ulfang.\n\nPlease, {class}, find and help him.", sourceObjective = "Sage Mistwalker has asked you to seek out and help Ulfang in the Rivenwood.\n\nIf you somehow lose the Worg Disguise, return to Sage Mistwalker for a replacement.\n\nProvided item:", completion = "You look and smell different... you are not one of my pack. Tell me your story; I have nothing but time while I am trapped in here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11324] = { id = 11324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alpha Worg", description = "When you've eaten Talonshrike's eyes, you should be able see Garwal and rip out his throat!\n\n{race}-thing, seek out and slay Garwal in the western Rivenwood. After you have killed him, go and tell Mistwalker that I am once more the alpha worg!", sourceObjective = "Ulfang has asked you to slay Garwal. Then, return the Worg Disguise to Sage Mistwalker at Steel Gate.", progress = "{name}, you have returned. What news of Ulfang?", completion = "Garwal was not a worg at all! I know of these creatures... they are called worgen.\n\nBut, Ulfang indicated that it came south from the Grizzly Hills? Odd. There aren't any worgen there.\n\nI thank you for helping to restore Ulfang to his proper place amongst his pack. Now we both will be able to sleep peacefully.\n\nPlease, you must accept this as a sign of gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[11325] = { id = 11325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Worg's Clothing", description = "From my dreams, I know that Ulfang is in a cave on the snowy northwestern edge of the Rivenwood.\n\nHe is in great danger!\n\nI have devised a magical disguise that will make you appear as a worg while you are within the Rivenwood. The disguise is weak, relying upon the strange magics of that haunted wood. While it will only convince the worgs, it will allow you to get close to Ulfang.\n\nPlease, {class}, find and help him.", sourceObjective = "Watcher Moonleaf has asked you to seek out and help Ulfang in the Rivenwood.\n\nIf you somehow lose the Worg Disguise, return to Watcher Moonleaf for a replacement.\n\nProvided item:", completion = "You look and smell different... you are not one of my pack. Tell me your story; I have nothing but time while I am trapped in here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11326] = { id = 11326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alpha Worg", description = "When you've eaten Talonshrike's eyes, you should be able see Garwal and rip out his throat!\n\n{race}-thing, seek out and slay Garwal in the western Rivenwood. After you have killed him, go and tell Moonleaf that I am once more the alpha worg!", sourceObjective = "Ulfang has asked you to slay Garwal. Then, return the Worg Disguise to Watcher Moonleaf at Steel Gate.", progress = "{name}, you have returned. What news of Ulfang?", completion = "Garwal was not a worg at all! The thing you describe him turning into sounds a lot like a worgen!\n\nBut, Ulfang said that it came south from the Grizzly Hills? Odd. There aren't any worgen there.\n\nI thank you for helping to restore Ulfang to his proper place amongst his pack. Now we both will be able to sleep peacefully.\n\nPlease, you must accept this as a sign of gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[11327] = { id = 11327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Package Retrieval", description = "Well darn, we need some of that plague-stuff.\n\nI know!\n\nWhile you were destroying the vats, I happened to spy one of the apothecaries from New Agamand being pulled into Halgrind by the vrykul down in there. Poor fella'.\n\n{name}, I'd bet anything that apothecary has the goods on him. Think you could go into Halgrind and retrieve his package?", sourceObjective = "Scout Knowles has asked you to retrieve the Apothecary's Package from inside Halgrind. Once you have it, return to the scout at the Ember Spear Tower.", progress = "That place looks like a nightmare. Vrykul or not, no one deserves to be the victim of the Royal Apothecary Society.\n\nGlad I'm standing safely over here. You find that package yet?", completion = "Holy... what the hell?! Look at this stuff!\n\nWe need to get this back to the keep a.s.a.p.!", sourceObjectiveStatus = "unverified-source-field" }
quests[11328] = { id = 11328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Forsaken Intel", description = "Right, so I think you should get this stuff over to Peppy Wrongnozzle back at the keep. She's something of an amateur alchemist, but she's the only one we've got.\n\nOne thing about Peppy; she does love her drink. So, you'll likely find her at the tavern 'soaking up the atmosphere'.\n\nI'm sure she'll know what to do.", sourceObjective = "Scout Knowles has asked you to deliver the Apothecary's Package to Peppy Wrongnozzle at Westguard Keep.", progress = "Yeah, whadya want ...hic?", completion = "Oh... hey, that'sh different!\n\nOkay, let me shee that shtuff. I jusht love tinkering with alchemy!\n\nInteresting, interesting... here, I think I know jusht what to do. A little mixing of that with the jusht the right amount of thish.\n\nYou know, I think a little dash of this rotgut will help, too ...hic!", sourceObjectiveStatus = "unverified-source-field" }
quests[11329] = { id = 11329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'll Try Anything!", description = "I never want to see another barrel of salted fish as long as I live! Filling barrels day in and day out, and there are still more to be filled!\n\nI wish I hadn't used up all that bait I bought from Nat Pagle. Worked like magic, it did. Now I'm lucky if I can catch a fish an hour!\n\nI hear the northern barbfish make pretty good bait, but who's crazy enough to dive into a freezing cold lake and hack up the water plants in search of them? Not me... but maybe, just maybe, I can persuade you to...", sourceObjective = "Christopher Sloan at Fort Wildervar wants you to bring him 5 Northern Barbfish.", progress = "You look like you're still in one piece. Get any of that bait?", completion = "Well, these certainly are ugly enough, but I suppose I don't care if it actually works. I'll be relieved once the expedition has passed through and I can go back to simply fishing for my dinner.", sourceObjectiveStatus = "unverified-source-field" }
quests[11330] = { id = 11330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Absholutely... Thish Will Work!", description = "Voila, inshtant plague vacshine!\n\nBut I sure as heck am not going to try thish on myself. And I know you don't want to be my tesht shubject!\n\nOh, I've got... I've got an idea!\n\nWe've got a vrykul prishoner being held down in the cells under the keep. Why don't you take thish mix I whipped up down there, and get that giant to drink it ...hic?!", sourceObjective = "Peppy Wrongnozzle at Westguard Keep has suggested that you take her Peppy's Special Mix and administer it to the Dragonflayer Vrykul Prisoner to witness its results.", completion = "Huh? Well that sucks! Darn, I made thingsh worsh. In fact, I think I perfected their plague for them ...hic!\n\n<Peppy grimaces and takes a huge gulp of whatever noxious brew she's been drinking.>\n\nWell, I wash hoping that it wouldn't come down to thish, but it looks like there'sh no alternative ...hic.", sourceObjectiveStatus = "unverified-source-field" }
quests[11331] = { id = 11331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Tell Him ...Hic!", description = "Here'sh the deal. I'm not going to the captain with thish news. I'm an amateur alchemist, thish ishn't my job, and I'm on break!\n\nBeshides, he'sh a big grumpkin... and you know him better than I do!\n\nSho, jusht go up into the keep and tell him. I'm sure he'll be reashonable about the whole thing ...hic.\n\n<Peppy turns back to her drinking.>", sourceObjective = "Peppy Wrongnozzle has suckered you into giving the bad news about the Forsaken plague to Captain Adams. Visit him at Westguard Keep.", completion = "Yes, {name}, what is it now?\n\nWHAT?!! A Forsaken super plague that melts you in no time?\n\nYou oozed my vrykul prisoner?\n\n\n\nAlright, I know what we need to do. Or rather, what YOU need to do!", sourceObjectiveStatus = "unverified-source-field" }
quests[11332] = { id = 11332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Plague This!", description = "The Royal Apothecary Society thinks they're going to perfect a new plague to melt us down where we stand?!\n\nNot on my watch!\n\nGet out to the courtyard and speak with Greer Orehammer. He's got a gryphon and some bombs ready for you. I want you to bomb the plague tanks at New Agamand to smithereens!", sourceObjective = "Captain Adams has ordered you to get 5 bomb hits on the Plague Tanks at New Agamand. Do not return to him at Westguard Keep until you have accomplished that.", completion = "Nicely done, {name}, nicely done!\n\n\n\nThat'll show those good-for-nothing Forsaken to think about messing with us!\n\nI'd say you've earned yourself something from the treasury!", sourceObjectiveStatus = "unverified-source-field" }
quests[11333] = { id = 11333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the World of Spirits", description = "While the Explorers' League may discern bits and pieces of the past through their archaeological findings and the Vice Admiral might extract some knowledge of the present through brute force, the truth lies with the spirits.\n\nWith the proper reagents I am able to see into the spirit world. It is there that the past, present and future of Northrend resides.\n\nIf you wish to learn more, I will require my reagent pouch. It was lost in a ship that is now at the bottom of Daggercap Bay, just east of here.", sourceObjective = "Thoralius the Wise at Valgarde wants you to find his Reagent Pouch.", progress = "Have you found my reagent pouch?", completion = "A bit worse for the wear but still functional.\n\n<Thoralius reaches into the pouch and removes some odd looking roots.>\n\nNow to place them in the fire and inhale!\n\n<Thoralius throws the roots into the smoldering incense burner.>\n\n<Thoralius inhales deeply. His body begins to quiver.>\n\nWha... What... It cannot be... I cannot...", sourceObjectiveStatus = "unverified-source-field" }
quests[11334] = { id = 11334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He Shoots, He Scores!" }
quests[11335] = { id = 11335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle of Arathi Basin that demands immediate reinforcements.\n\nReturn to me with news of victory, {name}.  We cannot allow the Horde scum to secure the resources that are rightfully ours!", sourceObjective = "Win an Arathi Basin battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", progress = "Tell me, {name}.  What news do you bring from the front?", completion = "Excellent news, {class}!  If our tactical deployments continue to be this successful, the Horde will be in full retreat before long.", sourceObjectiveStatus = "unverified-source-field" }
quests[11336] = { id = 11336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Alterac Valley", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle for Alterac Valley that's in most need of brave combatants.\n\nGo now, {name}, and aid the Stormpike Expedition.  We cannot allow the Frostwolf Clan to get away with the violence they've inflicted on our brethren!", sourceObjective = "Win an Alterac Valley battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", progress = "Tell me, {name}.  What news do you bring from the front?", completion = "Just what I wanted to hear!  A victory in Alterac Valley - even a temporary one - is crucial to our overall strategy against the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[11337] = { id = 11337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Eye of the Storm", description = "The fight against the Horde knows no boundaries, {name}.  Even in Outland, territorial disputes and old hatreds are enough to tip the scales in favor of war.\n\nGo into the Eye of the Storm and make sure the Alliance prevails in Outland just like it has in Azeroth.", sourceObjective = "Win an Eye of the Storm battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", progress = "Tell me, {name}.  What news do you bring from the front?", completion = "We've come one step closer to achieving total victory over the Horde.  We cannot allow the enemy to obtain a foothold in this world or any other.", sourceObjectiveStatus = "unverified-source-field" }
quests[11338] = { id = 11338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory.\n\nTheir need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!", sourceObjective = "Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", progress = "What news do you bring from the front, {name}?", completion = "Excellent work, {name}.  The integrity of our borders must be preserved at all costs!", sourceObjectiveStatus = "unverified-source-field" }
quests[11339] = { id = 11339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "Arathi Basin is on the verge of being lost to Alliance forces.  We must send reinforcements at this very moment or all our efforts will have been in vain.\n\nDo not delay, {class}, go to Arathi Basin and crush the enemy.  Victory to the Horde!", sourceObjective = "Win an Arathi Basin battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", progress = "You're back already.  Do you bring news of victory?", completion = "You've brought great honor to the Horde, {name}.  Your victory today will ensure a thousand victories tomorrow!", sourceObjectiveStatus = "unverified-source-field" }
quests[11340] = { id = 11340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Alterac Valley", description = "We've recently come extremely close to driving the Stormpike invaders from Alterac Valley.  As a result we're redirecting all our reinforcements to aid the Frostwolf Clan.\n\nA decisive victory there would free up the resources we need to crush the Alliance scum on all the other battlefronts.\n\nGo, {name}.  Earn great honor by heeding the call of the brave Frostwolf warriors.", sourceObjective = "Win an Alterac Valley battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", progress = "You're back!  Do you bring news of victory?", completion = "There is no greater honor than driving invaders from Horde territories.  We salute your great courage in aiding our forces today!", sourceObjectiveStatus = "unverified-source-field" }
quests[11341] = { id = 11341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Eye of the Storm", description = "We will fight and crush the enemy wherever we find them.  Azeroth, Outland, the place makes no difference.\n\nWe cannot allow the Alliance to establish superiority in the Eye of the Storm.  Take the battle to them today... tomorrow it might be too late!", sourceObjective = "Win an Eye of the Storm battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran,  or Shattrath.", progress = "You're back!  Do you bring news of victory?", completion = "You bring honor to us all, {name}.  We must show the enemy that we will fight them wherever we find them.", sourceObjectiveStatus = "unverified-source-field" }
quests[11342] = { id = 11342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Alliance is an insidious enemy, {name}.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens.\n\nToday we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!", sourceObjective = "Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", progress = "You're back!  Do you bring news of victory?", completion = "The Horde is in your debt, {name}.  You've made your people proud with your courage in defending our lands.", sourceObjectiveStatus = "unverified-source-field" }
quests[11343] = { id = 11343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Echo of Ymiron", description = "The spirit world has fallen under the sway of the Lich King. Fearsome creatures made of pure nightmare now stand watch over the realm of the elements. I sense that these val'kyr are guarding a terrible secret.\n\nI am too old and weak to survive another journey. You must go in my place, {name}.\n\nTake this incense burner to Wyrmskull Village and use it to enter the spirit world. Find the large dwelling in the northeast! Avoid the val'kyr at all costs lest they make you a permanent fixture in their world.", sourceObjective = "Thoralius the Wise wants you to search Wyrmskull Village while you are in the spirit world and find information about the Secrets of Wyrmskull.", progress = "What have you discovered?", completion = "I do not understand. The creatures that you saw looked like the vrykul that are attacking Valgarde?", sourceObjectiveStatus = "unverified-source-field" }
quests[11344] = { id = 11344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anguish of Nifflevar", description = "All that we know of the vrykul indicates that they only recently appeared in Northrend. Why, then, are we seeing vrykul in visions that date back 15,000 years? Surely if the vrykul had previously existed in Northrend we would have known.\n\nYou must press on to Nifflevar. To get there you must go northeast, through Wyrmskull Village, and take the path leading up through the dam. Nifflevar is on the bluffs of the fjord.\n\nUse the incense burner once you arrive at Nifflevar and search the area for clues.", sourceObjective = "Thoralius the Wise wants you to search Nifflevar while you are in the spirit world and find information about the Secrets of Nifflevar.", progress = "What have you discovered?", completion = "Human children born of vrykul? And Ymiron ordered the deaths of all human born offspring?\n\n<Thoralius goes silent for a moment.>\n\nAs much as I wish to deny what is so plainly presented to me, I cannot. There is no extinct \"missing link\" to humans as the Explorers' League proposed. The vrykul are the missing link. They are the progenitors of humanity.", sourceObjectiveStatus = "unverified-source-field" }
quests[11345] = { id = 11345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prizes for Pellets" }
quests[11346] = { id = 11346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Book of Runes", description = "The vast rocky area to the southeast, Giants' Run, has been overrun by Iron Dwarves. Scouts have reported seeing the dwarves coaxing stone giants from the ground, then carving runes on them.\n\nI can't fathom their motives, but I suspect they're somehow trying to turn the giants into weapons. The iron rune stonecallers and binders carry large tomes with them, which must contain the runes they're carving on the giants.\n\nCapture the pieces of this book, assemble them, and bring it back to me, {name}.", sourceObjective = "Prospector Belvar at Fort Wildervar wants you to bring him The Book of Runes.", progress = "Have you recovered the book?", completion = "<Prospector Belvar browses the book of runes.>\n\nHmm... there's so much here. I'm going to need some time to study it, and if we hope to understand these runes, we'll need to try to make our own.", sourceObjectiveStatus = "unverified-source-field" }
quests[11348] = { id = 11348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rune of Command", description = "Can you feel the power emanating from the runes I've carved on this tablet? They're smaller versions of the runes that the Iron Dwarves are using. We'll use it to shut down their operation.\n\nTake it to Giants' Run and use it on a stone giant that the dwarves have not altered.\n\nThe giant should obey you, but I've tailored the runes to restore it to its natural state after a time. The giant may prove a valuable ally in the battle against Binder Murdis, the leader of the Iron Dwarf forces at Giants' Run.", sourceObjective = "Prospector Belvar at Fort Wildervar wants you to test the Rune of Command and defeat Binder Murdis.", progress = "Have you tried the rune?", completion = "You've done well in defeating Binder Murdis, but the Iron Dwarves won't give up easily.\n\nWe've made a lot of progress in understanding how they manipulate runes. Perhaps next time we encounter them, our knowledge will give us an advantage.", sourceObjectiveStatus = "unverified-source-field" }
quests[11349] = { id = 11349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastering the Runes", description = "I've got a set of picks, hammers, and chisels with me, but they won't work for carving these runes. The tools used by the Iron Dwarves are imbued with magic during their forging.\n\nWhen they're used to carve runes, the symbols form much more than mere words. These runes have the power to bind, compel, and twist.\n\nI believe I know how it works, but without a set of those tools, I can't be certain. Look for kits resembling mine near the Iron Dwarf pavilions at Giants' Run and bring them to me.", sourceObjective = "Bring a set of Iron Rune Carving Tools to Prospector Belvar at Fort Wildervar.", progress = "Have you returned with those tools?", completion = "<Belvar handles the tools carefully.>\n\nI'm going to try these out. If we're to understand the Iron Dwarves' motives and defeat them, I need to know exactly what the runes are doing.", sourceObjectiveStatus = "unverified-source-field" }
quests[11350] = { id = 11350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Book of Runes", description = "Chieftain Ashtotem dispatched me on a scouting mission to Giants' Run, a broad, rocky plateau to the southeast, past the Frozen Glade.\n\nThe area has been taken over by Iron Dwarves who seem to be altering the giants as they emerge from the earth.\n\nThe iron rune stonecallers and binders carry large tomes with them, which must contain the runes they're carving on the giants.\n\nCapture the pieces of this book, assemble them, and bring it back to me. It's the only way we'll understand their plans.", sourceObjective = "Longrunner Pembe at Camp Winterhoof wants you to bring him The Book of Runes.", progress = "Have you recovered the book?", completion = "<The longrunner browses the book of runes.>\n\nI'm no loremaster, but I have some familiarity with the language of the Iron Dwarves. I think the runes they're carving on the giants are derived from their spoken language, but there are some differences.", sourceObjectiveStatus = "unverified-source-field" }
quests[11351] = { id = 11351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastering the Runes", description = "I think I've figured out what the Iron Dwarves are doing. The tools they use are imbued with magic during their forging.\n\nWhen they're used to carve runes, the symbols form much more than mere words. These runes have the power to bind, compel, and twist.\n\nIf I had a set of those tools, I could mimic the runes in the book. I captured one of these boxes from one of the pavilions at Giants' Run, but it was empty. Look for similar boxes and recover a set of tools from them.", sourceObjective = "Bring a set of Iron Rune Carving Tools to Longrunner Pembe at Camp Winterhoof.", progress = "Have you returned with those tools?", completion = "<Pembe examines the tools.>\n\nThese are more delicate than I'd thought. Allow me a moment to try them out.", sourceObjectiveStatus = "unverified-source-field" }
quests[11352] = { id = 11352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rune of Command", description = "Can you feel the power emanating from the runes I've carved on this tablet? They're smaller versions of the runes that the Iron Dwarves are using. We'll use it to shut down their operation.\n\nTake it to Giants' Run and use it on a stone giant that the dwarves have not altered.\n\nThe giant should obey you, but I've tailored the runes to restore it to its natural state after a time. The giant may prove a valuable ally in the battle against Binder Murdis, the leader of the Iron Dwarf forces at Giants' Run.", sourceObjective = "Longrunner Pembe at Camp Winterhoof wants you to test the Rune of Command and defeat Binder Murdis.", completion = "You've done well in defeating Binder Murdis, but the Iron Dwarves won't give up easily.\n\nAs my people move north, I'm certain we will encounter the Iron Dwarves again. Next time, we will be prepared to thwart them before they can dig in.", sourceObjectiveStatus = "unverified-source-field" }
quests[11354] = { id = 11354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Nazan's Riding Crop", description = "Today I have a buyer who is interested in a piece that's held by the mount of Illidan's herald. I, of course, speak of Vazruden the Herald and his dragon mount, Nazan.\n\nIf you want the finder's fee that I offer in return, find them flying above the Ramparts at Hellfire Citadel and return with the dragon's riding crop.\n\nMy sources tell me that the item in question is personally held by the dragon. It is said that Nazan refuses to allow Vazruden to strike him with it.", sourceObjective = "Wind Trader Zhareem has asked you to obtain Nazan's Riding Crop. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "The riding crop please.", completion = "Another soon-to-be satisfied customer. It looks like it's in fine condition. You are to be rewarded.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11355] = { id = 11355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "March of the Giants", description = "To the east, at Giants' Run, rune-inscribed stone giants have started to migrate north toward Frostblade Peak. What their ultimate destination is, I do not know.\n\nThe glowing runes inscribed in the stone flesh of the giants guide them on their journey.\n\nUse this pick to deactivate the runes on the giants' corpses and return with your findings.", sourceObjective = "Researcher Aderan at Fort Wildervar wants you to use the Runeseeking Pick on the corpses of 4 Runed Stone Giants.", completion = "<Researcher Aderan listens to your findings.>\n\nThe runes for \"north\" and \"west\" appeared multiple times? There's a highly reinforced command to move in that direction, but the runes are more than propulsion. Something is attracting them, but what?", sourceObjectiveStatus = "unverified-source-field" }
quests[11356] = { id = 11356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Costumed Orphan Matron", description = "During Hallow's End, human orphanages have organized trips for their orphans to visit Alliance countryside villages.  Those poor children would love to see a real {class} like yourself!\n\nWhy don't you visit them?  You'll find orphans at Goldshire in Elwynn Forest, Kharanos in Dun Morogh and Azure Watch in Azuremyst.  Speak to the children's ward, a costumed orphan matron, and she'll introduce you to the children.", sourceObjective = "Speak with a Costumed Orphan Matron in either Goldshire, Kharanos or Azure Watch.", completion = "You're here to visit the children!  Wonderful!  They have known such heartache in their short lives.  It is good that they see real heroes like you.  It really lifts their spirits!", sourceObjectiveStatus = "unverified-source-field" }
quests[11357] = { id = 11357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Masked Orphan Matron", description = "For Hallow's End, orc orphans were taken on a trip to many Horde villages.  The orphan matrons thought it would be good for them to see real heroes adventuring in the field.\n\nWhy don't you visit them?  A brave {class} like yourself could strengthen their spirits with tales of your valor!  Go to either Razor Hill in Durotar, Brill in Tirisfal Glades or Falconwing Square in Eversong Woods.  Speak with the masked orphan matron and she'll introduce you to the children.", sourceObjective = "Speak with a Masked Orphan Matron in either Razor Hill, Brill or Falconwing Square.", completion = "The children love to watch heroes at their work.  It is my hope that, one day, each of these orphans will grow into a strong member of the Horde, and ultimately die in glorious battle!\n\nAh, thoughts of such a fine fate brings mist to my eyes...", sourceObjectiveStatus = "unverified-source-field" }
quests[11358] = { id = 11358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lodestone", description = "If we can locate what's luring the giants northwest, we might be able to stop them before they reach their destination.\n\nAlthough I was able to decipher many of the runes on the samples you brought me, the ones I don't know concern me the most. When I visited Giants' Run, I noticed a large broken tablet jutting from the ground where the northeastern part of the area met the snow at the foot of Frostblade Peak. Take this sample, compare the runes with the tablet, and see what you can learn.", sourceObjective = "Researcher Aderan at Fort Wildervar wants you to compare the Rune Sample with the Broken Tablet.", progress = "Have you discovered what lodestone attracts the giants?", completion = "<Aderan listens as you describe your findings.>\n\nOf course! This Megalith must be the key to the Iron Dwarves' plans. We must destroy it before their plan comes to fruition!", sourceObjectiveStatus = "unverified-source-field" }
quests[11359] = { id = 11359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demolishing Megalith", description = "Binder Murdis created Megalith to be the most powerful of the runed giants and to lead them in their mission. Defeating Megalith will leave them lost and without direction. After the expeditionary force arrives, our soldiers will be able to isolate and defeat the remaining giants and oust their Iron Dwarf masters from their camps.\n\nSearch the foothills of Frostblade Peak, north of Giants' Run for Megalith and defeat him!", sourceObjective = "Defeat Megalith and return to Researcher Aderan at Fort Wildervar.", progress = "Do you bring news of Megalith's downfall?", completion = "You've done well in felling Megalith, but I wonder about his final words.\n\nYou're sure he said the Stoneforge?\n\nI know of no place with that name, but it sounds like a word with origins in the titans. What plans do the Iron Dwarves have for such a thing? This bears watching, {name}, for we must find it before the Iron Dwarves' plan comes to fruition.", sourceObjectiveStatus = "unverified-source-field" }
quests[11360] = { id = 11360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Brigade Practice", description = "With the Headless Horseman at large, the heroes of Goldshire are always ready to form a fire brigade.  Do you want to help?\n\nNorth of here, guards set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here, or the one near the fires.\n\nGood bye, {name}.  When you're done with fire brigade practice, please visit us again!", sourceObjective = "Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron.", progress = "Hello, {name}.  Have you been perfecting your fire fighting techniques?  Don't forget about the practice area to the north!", completion = "You're wet and smudged with soot!  You must have been extinguishing fires!\n\nWell done!  As an honorary member of the Fire Brigade, I beg you to return here if ever the village needs you!", sourceObjectiveStatus = "unverified-source-field" }
quests[11361] = { id = 11361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Training", description = "The grunts set up a fire training area outside the village.  These days, Razor Hill's buildings often catch fire -- you should lend a hand and train as a fire fighter!\n\nHead west out of Razor Hill, then turn right as you pass the village's wall.  Find the training area, then grab buckets and toss them on the practice fires.", sourceObjective = "Toss Water Buckets on 5 fires, then speak with the Masked Orphan Matron in Razor Hill.", progress = "Have you dowsed any fires, {name}?  The training area is west of Razor Hill's western exit.", completion = "Well done, {name}!  Children, take a good look at this {class}. Grow strong and brave like him and one day you too will fight for the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[11362] = { id = 11362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Keli'dan's Feathered Stave", description = "There is no accounting for taste. Take my most recent buyer for instance.\n\nThere is a blood orc within Hellfire Citadel known as Keli'dan the Breaker. He bears a most mundane stave; certainly nothing to take a second glance at. And yet, this is what my customer wishes.\n\nWho am I to say no?\n\nIf you desire my compensation, you will find him and his stave within the Blood Furnace.", sourceObjective = "Wind Trader Zhareem has asked you to obtain Keli'dan's Feathered Stave. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "We are speaking again... you must have the stave.", completion = "Perhaps I will have new feathers tied onto it before shipping it on to the buyer. I'm certain with so many arakkoa hereabouts it will not prove difficult. A small matter, and nothing to detract from your reward in any case.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11363] = { id = 11363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Bladefist's Seal", description = "Today I have a very wealthy collector in need of something very unique indeed.\n\nWarchief Kargath Bladefist carries upon his person his seal of command, which he uses to sign all official documents. I want you to retrieve it for me.\n\nYou will find him deep within the Shattered Halls. No doubt you will have to wade through a veritable army to get to him. I have no doubt that you will succeed.", sourceObjective = "Wind Trader Zhareem has asked you to obtain Bladefist's Seal. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "I have heard it whispered that the warchief has weapons in place of his hands. Is this true?", completion = "Truly a daring acquisition that the bards should put pen to parchment for. Here, you have more than earned this.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11364] = { id = 11364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Shattered Hand Centurions", description = "Do you question your master? Neither does Mah'duun.\n\nThe blood of the centurions of the Shattered Hand clan is what I seek. You will find them within the Shattered Halls of Hellfire Citadel.\n\nIf you want the bounty, you will not return until you have slain them all.", sourceObjective = "Nether-Stalker Mah'duun has tasked you with the deaths of 4 Shattered Hand Centurions. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", progress = "You have returned. The centurions all lay dead?", completion = "Very well, you have earned your bounty.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11365] = { id = 11365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "March of the Giants", description = "To the east, at Giants' Run, rune-inscribed stone giants have started to migrate north toward Frostblade Peak. I know nothing of their goals, nor of their destination.\n\nThe glowing runes inscribed in the stone flesh of the giants guide them on their journey. Fell some of these giants.\n\nTake this pick with you and use it on the corpses of the runed stone giants. It will deactivate the runes. Once you've tested enough giants, return to me with your findings.", sourceObjective = "Sage Edan and Camp Winterhoof wants you to use the Runeseeking Pick on the corpses of 4 Runed Stone Giants.", progress = "What have you found?", completion = "<The sage listens to your findings.>\n\nThe runes for \"north\" and \"west\" appeared over and over? I'm not an expert in these runes, but the repetition of them suggests a strong command.\n\nThese carvings are more than passive directions, though. They seem to pull the giants toward something, but what?", sourceObjectiveStatus = "unverified-source-field" }
quests[11366] = { id = 11366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lodestone", description = "We must find what's luring the giants northwest, so we can stop them before they reach their destination.\n\nWhile the rune samples gave us some clues, the unknown runes worry me.\n\nWhen I visited Giants' Run, I noticed a large broken tablet jutting from the ground where the northeastern part of the area met the snow at the foot of Frostblade Peak. Take this sample, compare the runes with the tablet, and see what you can learn about the identity of this lodestone.", sourceObjective = "Sage Edan at Camp Winterhoof wants you to compare the Rune Sample with the Broken Tablet.", progress = "Have you discovered what lodestone attracts the giants?", completion = "<Edan listens as you describe your findings.>\n\nMegalith? A literal transcription from the tablet! This Megalith must be the centerpiece of the iron ones' mysterious plans.", sourceObjectiveStatus = "unverified-source-field" }
quests[11367] = { id = 11367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demolishing Megalith", description = "Binder Murdis created Megalith to be a kind of keystone for the runed giants and to lead them in their mission. Defeating Megalith will leave them lost and without direction. I will ask Chieftain Ashtotem to divert some of our men as we move north and dedicate them to eliminating the last of the runed giants. Without their giants, the Iron Dwarves cannot stand against us.\n\nSearch the foothills of Frostblade Peak, north of Giants' Run for Megalith and defeat him!", sourceObjective = "Defeat Megalith and return to Sage Edan at Camp Winterhoof.", progress = "Do you bring news of Megalith's downfall?", completion = "You've done well in felling Megalith, but I wonder about his final words.\n\nYou're sure he said the Stoneforge?\n\nIt is not a name our people know, but it sounds like it might be a creation of the \"titans\" the ousiders speak of. The Iron Dwarves have ever been a cunning and dangerous foe, {name}. We must watch these giants and find this Stoneforge before they can carry out their plans.", sourceObjectiveStatus = "unverified-source-field" }
quests[11368] = { id = 11368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: The Heart of Quagmirran", description = "I have an unusual request. A certain wealthy individual that I am in contact with off-world is interested in a macabre piece.\n\nSpecifically, she wants the heart of Quagmirran.\n\nI hear that the beast has three, but one will suffice for our purposes. As I understand it, you can find Quagmirran resting within a deep pool of water at the Slave Pens.", sourceObjective = "Wind Trader Zhareem has asked you to obtain The Heart of Quagmirran. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "I trust that you know of a way to preserve the heart in transit?", completion = "Now that I think of it, it's a pity I didn't ask you to return with the other two hearts as well. Perhaps next time. In any case, you've earned your commission.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11369] = { id = 11369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: A Black Stalker Egg", description = "There is only ever one great mother of the marsh walkers in Zangarmarsh. She is always known as the Black Stalker, and she hatches from one of the eggs left behind when her mother dies.\n\nI have a buyer who is interested in one of those eggs. He mentioned something about adding her as a zoo attraction.\n\nIf you are interested in the reward I am offering, travel to the Underbog and slay the Black Stalker for her egg.", sourceObjective = "Wind Trader Zhareem wants you to obtain a Black Stalker Egg. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "We're speaking again because you have the egg? Outstanding, let me see it!", completion = "Is it not amazing to feel the life pulsing within the egg? I must hurry to deliver it to the purchaser. We wouldn't want it hatching here now would we?\n\nYour payment is ready.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11370] = { id = 11370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: The Warlord's Treatise", description = "While it is known that Warlord Kalithresh of the naga is a great warrior in his own right, there are fewer who know that he has codified all of his knowledge.\n\nOne of my customers is aware of it though, and is keenly interested in obtaining his treatise.\n\nI ask that you travel to the Steamvault in Coilfang Reservoir and obtain this book for me.", sourceObjective = "Wind Trader Zhareem has asked you to acquire The Warlord's Treatise. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "My customer grows restless. I believe he wishes to plumb the depths of the warlord's tactical thinking to help with one of his ongoing conflicts.", completion = "Indeed, I fear my customer will not have time to peruse the entirety of this book. Nevertheless, that is not our concern.  Here is your reward.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11371] = { id = 11371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Coilfang Myrmidons", description = "Mah'duun hears and obeys, and I now ask you to be my instrument.\n\nIt has been related to me that the myrmidons of the coilfang tribe must be destroyed. Seek them out within the humid confines of the Steamvault underneath Coilfang Reservoir.\n\nI will accept nothing less than their utter annihilation.", sourceObjective = "Nether-Stalker Mah'duun has asked you to slay 14 Coilfang Myrmidons. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", progress = "How fares your fight against the coilfang myrmidons?", completion = "I trust that it was a fight worthy of your time? Certainly this bounty will be.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11372] = { id = 11372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: The Headfeathers of Ikiss", description = "I've recently been approached by a tauren whose husband is about to be elevated to chieftain. She wishes to make a special addition to his headdress.\n\nSpecifically, she wants to obtain the headfeathers from the dastardly Talon King Ikiss.\n\nIf you are interested in collecting my reward, travel to Auchindoun's Sethekk Halls and find him.", sourceObjective = "Wind Trader Zhareem has asked you to acquire The Headfeathers of Ikiss. Deliver them to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "The time of the chieftain's ceremony grows near.", completion = "I am sure that these feathers will make a fine addition to the chieftain's headdress. You have earned your compensation, {class}.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11373] = { id = 11373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Shaffar's Wondrous Pendant", description = "Today I have a personal request of you, yet the reward will certainly match the danger.\n\nMy family has a 'history', shall we say, with Nexus-Prince Shaffar and his followers. If the amulet he wears were to fall into my hands then surely that would mean that he had been dealt with.\n\nIf the bounty I am offering is of interest to you then journey to his lair within Auchindoun's Mana-Tombs.", sourceObjective = "Wind Trader Zhareem wants you to obtain Shaffar's Wondrous Amulet. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Not many know that the source of Shaffar's magic rests solely within his amulet. Without it he is powerless.\n\nThen again, if you have it that must mean that he is dead.", completion = "<You sense a deep level of satisfaction from the wind trader.>\n\nGood, I am glad to hear of his demise. And perhaps I will be able to unlock the secrets of his amulet for myself. If not, then I will sell it for a handsome price.\n\nI trust that this reward is sufficient.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11374] = { id = 11374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: The Exarch's Soul Gem", description = "Within Auchindoun's Auchenai Crypts many unsavory experiments are undertaken in the pursuit of a greater understanding of the necromantic arts. Many are the spirits that are tortured or destroyed therein.\n\nI have a customer who is interested in the liberation of one of those spirits. I have been informed that this spirit is contained within a soul gem held by none other than Exarch Maladaar himself.\n\nSeek him out within the crypts with all due haste and return to me with the gem.", sourceObjective = "Wind Trader Zhareem has asked you to recover The Exarch's Soul Gem. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Can you imagine being trapped within a gem for all eternity?", completion = "You're quite the hero, {name}. I am certain that my customer will find a way to free the spirit of their loved one from within the gem. For a job well done, your payment awaits.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11375] = { id = 11375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Murmur's Whisper", description = "When I'm done speaking, you may not want to take this commission.\n\nI have an eccentric client who specializes in the study of dead realities. It is rumored that the being known as Murmur destroyed the last world from which he was summoned. The professor is interested in examining his 'whisper' as he called it to understand how it is that Murmur accomplished such a feat.\n\nWill you journey to the Shadow Labyrinth within Auchindoun and retrieve it for me?", sourceObjective = "Wind Trader Zhareem has asked you to obtain Murmur's Whisper. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "I'm not even certain what form a whisper is supposed to take in the physical world, but the professor assures me that you'll know it when you see it.\n\nPerhaps it is something akin to the being's voice box?", completion = "I was worried that you might not return. I trust that you didn't go deaf from fighting Murmur?\n\nHere is your reward. The professor will be pleased no doubt, though I worry what he ultimately wishes to do with this thing.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11376] = { id = 11376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Malicious Instructors", description = "Mah'duun has heard it said that none are as cruel as the six-armed demonesses inside the Shadow Labyrinth.\n\nGo to Auchindoun, seek them out, kill them all.\n\nIf you cannot accomplish so simple a task, we do not have anything further to say to one another.", sourceObjective = "Nether-Stalker Mah'duun wants you to kill 3 Malicious Instructors. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", progress = "The instructors, they are all dead? No?\n\nDid I not say not to return unless you had killed them all?", completion = "I am satisfied. He who speaks through the nether shall be as well. Mah'duun has your bounty prepared.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'deen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11377] = { id = 11377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revenge is Tasty", description = "I'm providing the catering for some unusual party guests tonight.  One of these fellows was flying around in Skettis and got knocked to the ground by a monstrous kaliri--his leg was broken badly.\n\nThey've requested something special for his get well party: Kaliri Stew.\n\nI can loan you my cooking pot so you can whip up a batch of stew for me.  The recipe itself is simple, but you'll need to get a giant kaliri wing and some cooked warp burgers.", sourceObjective = "The Rokk in Lower City has asked you to cook up some Kaliri Stew using his cooking pot. Return to him when it's done.", progress = "Do I smell something tasty?", completion = "Oh, I do smell something tasty!  I hope you gave that bird quite a good beating.\n\nPlease, help yourself to some of my extra stock.  I'm sure someone of your talent could put it to good use.", sourceObjectiveStatus = "unverified-source-field" }
quests[11378] = { id = 11378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: The Epoch Hunter's Head", description = "The tastes of my customers range from the mundane to the exotic. And sometimes they want to do very mundane things with the exotic objects they seek.\n\nSuch is the case with my latest request. My client, who shall remain nameless, wishes to obtain the head of the Epoch Hunter to mount on his wall.\n\n{class}, will you find a way to travel back in time to Old Hillsbrad and procure said head for my trophy-hunting patron?", sourceObjective = "Wind Trader Zhareem has asked you to obtain the Epoch Hunter's Head. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "The head of the Epoch Hunter... how does one come to the decision that they want it mounted on their wall?\n\nAnd even then, to not hunt the beast yourself, what does one say to their friends when asked how the fight went?\n\nHe'll lie, I suppose.", completion = "I see you are returned to the present time intact.\n\n<The wind trader looks around.>\n\nIt doesn't appear that anything has changed. But then again, how would I know?\n\nThat's a nice cut; my customer will be pleased. Here is your reward.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11379] = { id = 11379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Super Hot Stew", description = "I'm trying to invent something with some real zing.  But to be honest, I'm more of an idea goblin these days.  I've lost my sense of adventure.\n\nBut you... remind me of my younger days; ready to take on the world with a sword in one hand and a skillet in the other.\n\nI want you to take my beloved cooking pot and head out to Blade's Edge.  Throw in some shortribs and crunchy serpent--already cooked for extra flavor--and broil it over an abyssal's corpse, the only thing hot enough to do the trick.", sourceObjective = "The Rokk in Lower City has asked you to cook up some Demon Broiled Surprise using his cooking pot, two Mok'Nathal Shortribs and a Crunchy Serpent. Return to him when it's done.", progress = "Any luck with my little experiment?", completion = "Now look at that...\n\n<The Rokk takes a sip of the concoction and his face twists into a bizarre mask of pain and delight.>\n\nSweet A'dal that's good!  A cook with your potential shouldn't be without his proper materials.  Take some of my extra stock and make me proud.", sourceObjectiveStatus = "unverified-source-field" }
quests[11380] = { id = 11380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manalicious", description = "Wouldn't you know it, I think my foodstuffs are up to date and someone comes along and requests the unusual: Mana Berry Delight.\n\nUnfortunately, mana berries are only found in the eco-domes of Netherstorm.  Just don't bother looking around Stormspire--it's picked clean.\n\nI could only trust someone trained in the culinary arts to pick the best berries, so don't let me down!", sourceObjective = "The Rokk in Lower City has asked you collect 15 Mana Berries from the Eco-Domes in Netherstorm.", progress = "Any luck, friend?", completion = "Those are the juiciest mana berries I've ever seen.  I think I'm getting smarter just by looking at them.\n\nSince I no longer need most of my meat and fish stock, why don't you take some?  I'm certain you could make something delicious.", sourceObjectiveStatus = "unverified-source-field" }
quests[11381] = { id = 11381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soup for the Soul", description = "Death is in the air.  I've never had so many orders for my famous soup--it lifts your spirits and soothes the soul.\n\nAnd I know a fellow cook when I see one!  Would you like to help me out and get a cut of the profits?\n\nHere, take my cooking pot, gather some clefthoof meat and I'll let you in on a little secret.  What makes my soup so good for the soul?  It's not chicken--I cook it at the Ancestral Grounds in Nagrand to soak up all that spiritual stuff there.", sourceObjective = "The Rokk in Lower City has asked you to cook up some Spiritual Soup using his cooking pot. Return to him when it's done.", progress = "What smells so good?", completion = "That is a fine batch of spiritual soup if I ever did smell one.  Just a pinch of pepper and it's done.\n\nAs promised, here's your cut.  And because you did such a fine job, I'm going to throw in some of my extra stock.", sourceObjectiveStatus = "unverified-source-field" }
quests[11382] = { id = 11382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Aeonus's Hourglass", description = "I swear that some of my customers are crazy. There are possessions that you go after, and there are ones that you dare not even think of!\n\nMy current client is clearly over-the-top insane. He covets the hourglass that Aeonus holds.\n\nYes, you heard right, Aeonus of the Infinite Dragonflight!\n\nWho am I to argue since he's paying a king's ransom? So, ready to go to the Caverns of Time and travel to the Black Morass to retrieve it for me?", sourceObjective = "Wind Trader Zhareem has asked you to acquire Aeonus's Hourglass. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "If I were you, I would be very careful with time-travel. You wouldn't want to accidentally do something, like kill one of your ancestors, and then accidentally erase yourself from the present!", completion = "Odd that the sands in that thing are still falling upward. I think I will have it delivered to its new owner with all due haste.\n\nI thank you for a job well done, {class}. You have certainly earned your commission.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11383] = { id = 11383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Rift Lords", description = "Mah'duun knows where you must go. Mah'duun knows that you must kill rift lords. But, Mah'duun does not know exactly when.\n\nI know that does not make sense, but the voice on the winds was not more specific.\n\nTravel to the Black Morass through the Caverns of Time and the way shall be made clear.", sourceObjective = "Nether-Stalker Mah'duun wants you to kill 4 Rift Lords. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", progress = "We are speaking, but I sense that all of the rift lords are not yet dead.\n\nReturn again when they are, {class}.", completion = "You found your way back in time, and then back again. You must be a great {class}, {race}. The bounty is earned.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11384] = { id = 11384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: A Warp Splinter Clipping", description = "Not long ago, I was approached by a kaldorei druidess with a touching request. And plenty of gold, of course!\n\nIt would appear that the forces of Darnassus wish to restore an ancient of the arcane known as Warp Splinter. The giant tree has been confused or corrupted, I'm not certain, but you'll find it inside of the Botanica at Tempest Keep.\n\nShe said that all they would need to regrow him was a small clipping.", sourceObjective = "Wind Trader Zhareem has asked you to obtain a Warp Splinter Clipping. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Did you lose your way to the Botanica? You can't miss it... it's at Tempest Keep off of the eastern edge of the Netherstorm.", completion = "Aw, you did get it! It's so tiny. And yet, when the druids are done with it -- a process I am told will take a very long time -- Warp Splinter will be regrown anew.\n\nAnd here is your reward as promised.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11385] = { id = 11385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Sunseeker Channelers", description = "It has been whispered to Mah'duun that the channelers of the military unit known as the Sunseekers must be killed today.\n\nThey are to be found within the Botanica at Tempest Keep.\n\nYou want the bounty, you kill the channelers.", sourceObjective = "Nether-Stalker Mah'duun wants you to kill 6 Sunseeker Channelers. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", progress = "How can it be that we are speaking when the channelers are not all lying dead?", completion = "And now they are dead, channeling no longer. He who whispers upon the nether is satisfied and you have secured the bounty.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11386] = { id = 11386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Pathaleon's Projector", description = "I always assumed that Pathaleon the Calculator used magic to project his image across Outland. Apparently I was wrong.\n\nMy latest customer tells me that the blood elf uses a mechanical device for his communication with the leaders of Prince Kael'thas's special projects. As I understand it, he acquired it from the Zaxxis rebels in the Netherstorm.\n\nMy client wishes to obtain the projector. Why don't you pay Pathaleon a visit? He can be found within the Mechanar at Tempest Keep.", sourceObjective = "Wind Trader Zhareem has asked you to acquire Pathaleon's Projector. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "It's not that projector technology is something special in and of itself, but the range of this particular model is a true breakthrough!", completion = "I'm tempted to keep it for myself and return my client's money. It could certainly expand the reach of my business.\n\n<The wind trader sighs.>\n\nHowever, I have a reputation to uphold.\n\nSpeaking of my reputation, thank you for helping me to maintain it. Here is your commission.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11387] = { id = 11387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Tempest-Forge Destroyers", description = "There are mechanical constructs within the Mechanar which Mah'duun has been told must be dismantled.\n\nGo to Tempest Keep, find the tempest-forge destroyers and destroy them.\n\nThen you may return to collect the bounty.", sourceObjective = "Nether-Stalker Mah'duun wants you to destroy 5 Tempest-Forge Destroyers. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", completion = "Mah'duun enjoys fighting constructs; they are less messy than organic beings.\n\nThe bounty is yours.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11388] = { id = 11388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: The Scroll of Skyriss", description = "Today's client seeks something truly unique.\n\nIt is said that Harbinger Skyriss is a servant of the Old Gods. It is also said that he carries a large scroll that contains their instructions for his domination of life in the universe on their behalf.\n\nMy current buyer wishes to get <his/her> hands on that scroll, nevermind that <he/she> won't be able to read the language upon it.\n\nTravel to Tempest Keep's Arcatraz and get it for me, will you, {class}?", sourceObjective = "Wind Trader Zhareem has asked you to obtain The Scroll of Skyriss. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "It must be a very dangerous thing to do to meddle directly in the affairs of the Old Gods.\n\nBetter you than me!", completion = "I dare not touch the scroll lest I too risk the notice of the Old Gods. I will have one of my assistants handle its delivery.\n\nYou have more than earned your reward, {class}, and I wish you all the luck in the known worlds.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11389] = { id = 11389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Arcatraz Sentinels", description = "The sentinels within the Arcatraz have gone haywire. The prisoners run rampant and the guards attack those that would help.\n\nMah'duun hears the speaker on the nether winds. The speaker says to destroy the sentinels.\n\nAccomplish this and today's bounty is yours.", sourceObjective = "Nether-Stalker Mah'duun wants you to dismantle 5 Arcatraz Sentinels. Return to him in Shattrath's Lower City once that has been accomplished in order to collect the bounty.", completion = "With the sentinels destroyed, perhaps the naaru will ask the Consortium to replace them? Mah'duun does not know and does not care.\n\nYou have earned the bounty.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11390] = { id = 11390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I've Got a Flying Machine!", description = "Well, what are you waiting for, there's work to be done!\n\nHere's the keys to our flying machine. Grab three sacks of relics and haul them up to the crane platforms on the north and south sides of Steel Gate.  I'll mark them for you.\n\nHurry up! We haven't got all day!", sourceObjective = "The Steel Gate Chief Archaeologist wants you to transport 3 Sacks of Relics from the bottom of the site and take them to the platform on the north or south side of Steel Gate.\n\nUse the grappling hook on the flying machine to do this.\n\nReport back to him after you've done so.", completion = "Good job, though I think ye might be wanting a refresher course in basic piloting.\n\nWell, no matter, one warm body's as good as another. Here's yer haul for the day.", sourceObjectiveStatus = "unverified-source-field" }
quests[11391] = { id = 11391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steel Gate Patrol", description = "Eh? Yer back for another day's work?\n\nWell, alright, here's the keys. We don't need any haulin' today, so just keep an eye out for anything suspicious, okay?\n\nI've hooked her up with some rockets and a machine gun - just in case.", sourceObjective = "You're Steel Gate's ace pilot now, so the Steel Gate Chief Archaeologist wants you to keep patrol around the dig site and fight off anything that attacks.\n\nReport back to him when you're done with your patrol.", completion = "Nice shooting, ace.\n\nHere's your wages. Come back tomorrow for another round, ya hear?", sourceObjectiveStatus = "unverified-source-field" }
quests[11392] = { id = 11392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call the Headless Horseman", description = "Many dreary candles adorn this pumpkin shrine.", sourceObjective = "Take a Dreary Candle to the Loosely Turned Soil.", progress = "This dirt has been recently disturbed.  Earthworms lie in the topsoil, squirming to escape the dark depths beneath them.", completion = "Will you lay the candle down and call the Headless Horseman from his doomed rest?", sourceObjectiveStatus = "unverified-source-field" }
quests[11393] = { id = 11393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where is Explorer Jaren?", description = "{name}, my betrothed, Jaren, went west with a small group of explorers to check into rumors of artifacts on the Chillmere Coast. But there are murloc down there, and I fear the worst has befallen them.\n\nSurely you have time to see if they're alright? There's a way down to the beach just to the southwest, though watch out for the worgs and other things lurking in the woods.", sourceObjective = "Overseer Irena Stonemantle has asked you to locate her fiance, Explorer Jaren.", completion = "<The explorer beams a smile as you tell him who sent you. He continues in hushed tones.>\n\nIrena was concerned about me?  She gets that from her father you know.", sourceObjectiveStatus = "unverified-source-field" }
quests[11394] = { id = 11394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And You Thought Murlocs Smelled Bad!", description = "Originally I came down here to investigate some rumors about artifacts to be dug up. I knew that there were murlocs along the coast here, but I never in a million years thought I'd see this.\n\n<The explorer pokes his head out to look around the tree.>\n\nThe Scourge are out there, and they're changing murlocs, and anything else they can get their hands on, into the walking dead!\n\n{class}, I think it's our duty to do something about this. Think you could take out a good chunk of those Scourge?", sourceObjective = "Explorer Jaren has asked you to kill 15 Scourge of any type along the Chillmere Coast. Return to him once you have done so.", progress = "I don't know, {class}, it doesn't look like you've destroyed enough of them yet.", completion = "<Jaren seems very excited about your success, but motions you to keep your conversation to a whisper.>\n\nGreat job, {name}! That's a lot of Scourge goo all over your stuff though. You might want to think about a quick dip in the strait. It's cold, but it'll get you cleaned up right quick.", sourceObjectiveStatus = "unverified-source-field" }
quests[11395] = { id = 11395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's a Scourge Device", description = "The Scourge creature you just destroyed had this device held in its clutches. It has a jewel set into it which looks similar to the one that tops the scourging crystals.\n\nSurely, Explorer Jaren would like to have a look at this.", sourceObjective = "Deliver the Scourge Device to Explorer Jaren on the Chillmere Coast.", progress = "What an odd-looking device you have there, {class}. Let me have a closer look at it.", completion = "I know what this is! {name}, it's a controlling device for those scourging crystals!\n\nI bet anything that it can be used to shut down their force fields. Hmmm.", sourceObjectiveStatus = "unverified-source-field" }
quests[11396] = { id = 11396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Down Those Shields", description = "Look at the button on the side of the controller here. I bet if you got close enough to one of those scourging crystals, you could use the controller to bring its shield down. Then it would simply be a matter of destroying the thing before its shield goes back up.\n\nWhat do you say, {name}? You up for it? I can guarantee a nice reward for you if you can bring down those shields and destroy the crystals.\n\nIt's the least we can do to keep the Scourge from making more of their own kind.", sourceObjective = "Explorer Jaren on the Chillmere Coast has asked you to destroy 3 Scourging Crystals.", progress = "I don't know, {name}. I think you need to take out a few more of those things.", completion = "Nice!\n\n<Jaren looks around quickly to make sure that nothing noticed his outburst.>\n\nAlright, you certainly earned your pick of one of these things I found while I was down here.\n\nAnd, {name}, if you happen to find yourself back at Steel Gate, give Irena my love and let her know that I'm okay.", sourceObjectiveStatus = "unverified-source-field" }
quests[11397] = { id = 11397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And You Thought Murlocs Smelled Bad!", description = "I came here to investigate a rumor about a Scourge presence nearby. I expected murlocs along the coast down below, but I never thought I'd see this!\n\nThe Scourge are down there, and they're changing murlocs, and anything else they can get their hands on, into the walking dead!\n\n{class}, we will not suffer them to create more of their kind, especially not from murlocs! There is a ramp down to the beach just northwest of the camp. See to it that you deal with the Scourge in a timely fashion!", sourceObjective = "Apothecary Anastasia has asked you to destroy 15 Scourge of any type along the Chillmere Coast. Return to her at the Apothecary Camp once you have done so.", completion = "<Anastasia ponders your success for a moment.>\n\nA satisfactory job to be certain, yet somehow I sense that there's something else we should be doing to stop the efforts of the Scourge on that beach.", sourceObjectiveStatus = "unverified-source-field" }
quests[11398] = { id = 11398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's a Scourge Device", description = "The Scourge creature you just destroyed had this device held in its clutches. It has a jewel set into it which looks similar to the one that tops the scourging crystals.\n\nSurely, Apothecary Anastasia would like to have a look at this.", sourceObjective = "Deliver the Scourge Device to Apothecary Anastasia at the Apothecary Camp.", progress = "What's that you have there, {class}? Let me have a closer look at it!", completion = "I can tell you what this is, {name}. It's a controlling device for those scourging crystals down there!\n\nI bet anything that it can be used to shut down their force fields. Hmmm.", sourceObjectiveStatus = "unverified-source-field" }
quests[11399] = { id = 11399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Down Those Shields", description = "Look at the button on the side of the controller here. I bet if you got close enough to one of those scourging crystals, you could use the controller to bring its shield down. Then it would simply be a matter of destroying the thing before its shield goes back up.\n\nBrave enough to hazard another trip down there, {name}? I can guarantee a nice reward for you if you can bring down those shields and destroy the crystals.\n\nHow can you refuse if it means less Scourge, especially ones made from murlocs?", sourceObjective = "Apothecary Anastasia at the Apothecary Camp has asked you to destroy 3 Scourging Crystals.", completion = "<Anastasia turns and smiles at her succubus.>\n\nVery well, {name}, I concede that you have certainly earned a choice of one of these.", sourceObjectiveStatus = "unverified-source-field" }
quests[11400] = { id = 11400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewfest Riding Rams", description = "If you show this hand stamp to Pol Amberstill, the Ram Racing Apprentice, he'll allow you to purchase Brewfest riding rams.", sourceObjective = "Bring the \"Honorary Brewer\" Hand Stamp to Pol Amberstill near the entrance to the Brewfest Grounds in Dun Morogh.", progress = "Is that an \"Honorary Brewer\" stamp you've got on your hand?", completion = "Good job, {name}... you've won the trust of the festival's brewers, earning the right to purchase a Brewfest riding ram.", sourceObjectiveStatus = "unverified-source-field" }
quests[11401] = { id = 11401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call the Headless Horseman", description = "Many dreary candles adorn this pumpkin shrine, which grins, taunting...", sourceObjective = "Take a Dreary Candle to the Loosely Turned Soil.", progress = "This dirt has been recently disturbed.  Earthworms lie in the topsoil, squirming to escape the dark depths beneath them.", completion = "Will you lay the candle down and call the Headless Horseman from his doomed rest?", sourceObjectiveStatus = "unverified-source-field" }
quests[11402] = { id = 11402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clayton's Quest: Extreme!!", description = "Clayton wants you to find and slay twenty Evil Squirrels.", sourceObjective = "Seriously, go slay those Evil Squirrels!", sourceObjectiveStatus = "unverified-source-field" }
quests[11403] = { id = 11403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free at Last!", description = "Rage was my prison, {name}, and you have freed me.  Though I thought I did right, my soul now weeps for the terror and the death I have caused the good people of Azeroth.\n\nThank you for leading me back to the Light.  May I never again lose my way.\n\nTake this torn prayer book to an orphan matron, so the children will know that I will haunt them no more.", sourceObjective = "Take the Tome of Thomas Thomson to a Masked Orphan Matron in Durotar, Brill or Falconwing Square.", progress = "{name}, it is good to see you again.  I'm sure the children enjoy tales of your heroism.", completion = "What?  This holy tome once belonged to an infamous paladin of the Alliance.  Was he the Headless Horseman?  Does this mean that the Horseman is defeated?\n\nThis is a glorious day, {name}!  Your legend will shine bright, and may it last for twice the years of the Horseman's reign of fear.", sourceObjectiveStatus = "unverified-source-field" }
quests[11404] = { id = 11404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call the Headless Horseman", description = "Many dreary candles adorn this pumpkin shrine, which grins, taunting...", sourceObjective = "Take a Dreary Candle to the Loosely Turned Soil.", progress = "This dirt has been recently disturbed.  Earthworms lie in the topsoil, squirming to escape the dark depths beneath them.", completion = "Will you lay the candle down and call the Headless Horseman from his doomed rest?", sourceObjectiveStatus = "unverified-source-field" }
quests[11405] = { id = 11405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call the Headless Horseman", description = "Many dreary candles adorn this pumpkin shrine, which grins, taunting...", sourceObjective = "Take a Dreary Candle to the Loosely Turned Soil.", progress = "This dirt has been recently disturbed.  Earthworms lie in the topsoil, squirming to escape the dark depths beneath them.", completion = "Will you lay the candle down and call the Headless Horseman from his doomed rest?", sourceObjectiveStatus = "unverified-source-field" }
quests[11406] = { id = 11406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everything Must Be Ready", description = "When the expeditionary force moves north, Captain Adams expects everything to be ready at Fort Wildervar. The scouts and craftsmen there have been tasked with preparing the gear and rations for our men for the climb into the hills.\n\nThe captain's famous for his temper, so I want to send someone ahead to check on the preparations. Fort Wildervar is far to the northeast, beyond Skorn, up in the snow-covered areas near the border with Grizzly Hills. Find Gil Grisert there and make sure he is prepared.", sourceObjective = "Speak with Gil Grisert at Fort Wildervar.", completion = "So the quartermaster sent you?\n\n<Gil seems relieved.>\n\nTo be honest, we're running a bit behind here and we're going to need some help making our goals.\n\n<Gil shudders.>\n\nNone of the men want to brave the wrath of Captain Adams.", sourceObjectiveStatus = "unverified-source-field" }
quests[11407] = { id = 11407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bark for Drohn's Distillery!", description = "So, do you want to help bring strength and honor to Brewfest?  We need you to shout at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.\n\nWe'll lend you a racing ram for 4 minutes and also give you these racing reins.\n\nBe careful though, the cheap goblins didn't put any apple crates along the way.", sourceObjective = "Spread the word about Brewfest at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.", progress = "Have you finished spreading the word about Brewfest?", completion = "You kept your word and let people know about our brewmasters.  Thank you. We promised you these tokens, and gladly give them to you.  I imagine the trolls are a bit more stingy with handing over their tokens...\n\nCome back another day to help us spread the word about Brewfest.", sourceObjectiveStatus = "unverified-source-field" }
quests[11408] = { id = 11408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bark for T'chali's Voodoo Brewery!", description = "We need to spread the word about the trolls at Brewfest.  Ya need to shout at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.\n\nBut I'll make it easy for ya, I'll lend you a racing ram for 4 minutes.  I'll also give you these racing reins.\n\nBe careful though, the goblins didn't put any apple crates along the way.  They are cheap like that.", sourceObjective = "Spread the word about Brewfest at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.", progress = "Have you finished spreading the word about Brewfest?  But more importantly, did you let people know about the amazing troll brew?", completion = "Ya did it!  We gotta get ready for the flood of customers that are sure to come our way!  Thanks!\n\nOh, that's right, and we promised you a reward.  Can't forget about that...\n\nFeel free to stop by again another day to help us spread the word some more.", sourceObjectiveStatus = "unverified-source-field" }
quests[11409] = { id = 11409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Now This is Ram Racing... Almost.", description = "So you want to check out the racing rams?  The dwarves think they have got a handle on it, but let's be honest, they are drunk most of the time, so how hard can it really be?\n\nNow before I let you strut your stuff, you'll need to show me that you can handle these fine, legally obtained creatures.\n\nSo here's the deal:  I'll lend you some racing reins and the use of a ram. You need to prove to me that you can handle using these rams.\n\nKeep the ram at a trot, canter and gallop for 8 seconds each.", sourceObjective = "You have 4 minutes to ride the ram and maintain 3 different levels of speed for 8 seconds.", completion = "Hey, that wasn't too bad... are you sure you're not a dwarf?\n\nSo there's plenty more racing to be had and it's not just from me.  All over the Brewfest grounds you'll find people in need of a decent ram racer.  So go and make yourself useful.\n\nOh and don't forget, these rams were legally obtained.  I just want to make sure we're clear.", sourceObjectiveStatus = "unverified-source-field" }
quests[11410] = { id = 11410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The One That Got Away", description = "The barbfish you brought should work well as bait for most fish, but I fear it'll attract a monster!\n\nWhen I first arrived, I put some of Nat Pagle's favorite bait on my hook and cast it into the water. A huge monster latched on, with giant teeth and icicles hanging from its fins!\n\nWould've pulled me into those icy waters if I hadn't cut the line! I can't use the new bait until ol' Frostfin's been dealt with. Use this bait near the sunken boat in the middle of the lake. He won't be able to resist!", sourceObjective = "Christopher Sloan at Fort Wildervar wants you to defeat Frostfin.", progress = "I'm itching to try out the new bait.\n\nHave you had any luck with Frostfin?", completion = "At last, we can finally fish in peace! 'Course, by the time we catch anything, the expedition'll arrive and claim it all for themselves.\n\nYou have our thanks, {name}. Don't be a stranger 'round here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11411] = { id = 11411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camp Winterhoof", description = "In my travels as a courier, I've seen a number of strange denizens of the Howling Fjord, but one group stands out. From a distance, they look like tauren, but upon closer inspection, they're quite different -- sturdier and shaggier.\n\nI found one of their settlements far to the north, beyond Halgrind, Skorn, and the northern forests. Camp Winterhoof, it's called, and it sits in the foothills of Gjalerhorn near the border with Grizzly Hills. Make contact with them, and see if they might be of use to us.", sourceObjective = "Speak to Chieftain Ashtotem at Camp Winterhoof.", sourceObjectiveStatus = "unverified-source-field" }
quests[11412] = { id = 11412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There and Back Again", description = "Am I glad you're here.  We are in big trouble!  The goblin that was supposed to be bringing us more brew had an accident on his way from Bladefist Bay.  You gotta get us that brew!\n\nI'll put you on one of my racing rams and you follow the road to Bladefist Bay.\n\nOnce you get near him he'll toss you a keg, then you run the keg back here and toss the keg to my more capable assistant.  For now, all we want are 3 kegs.  Do a good job and maybe we'll have another job for you.", sourceObjective = "Get a keg from the goblin stranded on the road to Bladefist Bay and return it to Ram Master Ray's assistant. Do this 3 times before your ram goes away.", progress = "Did you see the mess that goblin made?  I hope you didn't do too much reckless off-roading.", completion = "Thanks for your help!  As long as Brewfest is going, the Dark Iron dwarves are attacking and our supplier is stuck in that canyon, I'll need some help shipping kegs.  So if you want to work for more tokens, talk to me every day.\n\nHere are the tokens we promised you.  Have fun!", sourceObjectiveStatus = "unverified-source-field" }
quests[11413] = { id = 11413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Did Someone Say \"Souvenir?\"", description = "Not only are we supplying brew to everyone, we also have steins to give out!  Beautiful, commemorative steins all obtained by the most legal of means!  Here's a voucher for one.\n\nTalk to Blix near the back of the Brewfest camp.  He's pretty strange, even more so now that he's always wearing those goggles.  He'll handle the voucher for you, and any other Brewfest transaction.", sourceObjective = "Redeem the Brewfest Stein Voucher with Blix Fixwidget in the back of the Brewfest camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[11414] = { id = 11414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brother Betrayers", description = "Watcher Moonleaf is from my dreams! If you are her friend, you are mine.\n\nI was alpha male until the last full moon. Then the strange white worg, Garwal, came from the north, and with the help of my once-brothers, he quickly became alpha worg. There is something unnatural about him.\n\nTo help, you must first kill those who betrayed me.\n\nBjomolf hunts to the northwest of a place called Steel Gate. And look for Varg to the southeast, near the West Spear Tower.\n\nThey will not be fooled by your form.", sourceObjective = "Ulfang has asked you to kill the traitorous worgs, Bjomolf and Varg. Return to him in disguise in the Rivenwood after you have done so.\n\nIf you somehow lose the Worg Disguise, return to Watcher Moonleaf for a replacement.", progress = "<A low growl rises from Ulfang's throat.>\n\nBjomolf and Varg are not dead!", completion = "The smell of their blood upon your muzzle pleases me. Brothers should not turn on each other.", sourceObjectiveStatus = "unverified-source-field" }
quests[11415] = { id = 11415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brother Betrayers", description = "Mistwalker is from my dreams! If you are his friend, you are mine.\n\nI was alpha male until the last full moon. Then the strange white worg, Garwal, came from the north, and with the help of my once-brothers, he quickly became alpha. There is something unnatural about him.\n\nTo help, you must first kill those who betrayed me.\n\nBjomolf hunts to the northwest of a place the two-legs call Steel Gate. And look for Varg to the southeast, near the West Spear Tower.\n\nThey will not be fooled by your form.", sourceObjective = "Ulfang has asked you to kill the traitorous worgs, Bjomolf and Varg. Return to him in disguise in the Rivenwood after you have done so.\n\nIf you somehow lose the Worg Disguise, return to Sage Mistwalker for a replacement.", progress = "<A low growl rises from Ulfang's throat.>\n\nBjomolf and Varg are not dead!", completion = "The smell of their blood upon your muzzle pleases me. Brothers should not turn on each other.", sourceObjectiveStatus = "unverified-source-field" }
quests[11416] = { id = 11416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes of the Eagle", description = "Garwal hides himself behind an unnatural magic. None can see him unless he wants you to. There may be one chance we can take, though.\n\nMy enemy, the great eagle, Talonshrike, is said to have eyes that can see anything. If you were to take her eyes, then you would surely be able to see Garwal.\n\nTalonshrike keeps her nest at the base of a waterfall just to the southwest of the vrykul place called Skorn. If you touch the eggs in her nest, she will come down from the sky to kill you.\n\nGet her eyes.", sourceObjective = "Ulfang has asked you to collect the Eyes of the Eagle. Return to him in disguise in the Rivenwood after you have done so.\n\nIf you somehow lose the Worg Disguise, return to Watcher Moonleaf for a replacement.", progress = "You have the eyes of the eagle?", completion = "<Ulfang howls loudly at your defeat of his great eagle enemy.>\n\nThe honor of the kill is yours. I wish that it had been my maw to finally close upon her neck.\n\nLet us not waste the sacrifice that she has made for us. Here, eat them!", sourceObjectiveStatus = "unverified-source-field" }
quests[11417] = { id = 11417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes of the Eagle", description = "Garwal hides himself behind an unnatural magic. None can see him unless he wants you to. There may be one chance we can take, though.\n\nMy enemy, the great eagle, Talonshrike, is said to have eyes that can see anything. If you were to take her eyes, then you would surely be able to see Garwal.\n\nTalonshrike keeps her nest at the base of a waterfall just to the southwest of the vrykul place called Skorn. If you touch the eggs in her nest, she will come down from the sky to kill you.\n\nGet her eyes.", sourceObjective = "Ulfang has asked you to collect the Eyes of the Eagle. Return to him in disguise in the Rivenwood after you have done so.\n\nIf you somehow lose the Worg Disguise, return to Sage Mistwalker for a replacement.", progress = "You have the eyes of the eagle?", completion = "<Ulfang howls loudly at your defeat of his great eagle enemy.>\n\nThe honor of the kill is yours. I wish that it had been my maw to finally close upon her neck.\n\nLet us not waste the sacrifice that she has made for us. Here, eat them!", sourceObjectiveStatus = "unverified-source-field" }
quests[11418] = { id = 11418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Call Him Steelfeather", description = "We see one brave hippogryph circling over the fort, then swooping down and taking prey. Jethan over there has taken a couple of shots at the creature, but his arrows bounced right off!\n\nWe've taken to calling this remarkable creature Steelfeather, but we can't see why he prefers the area around Fort Wildervar. Most hippogryphs are wary of people.\n\nResearcher Aderan has helped us fashion a charm from one of the creature's feathers. He claims it will allow the user to see through Steelfeather's eyes.", sourceObjective = "Locate Steelfeather circling Fort Wildervar and use the Feathered Charm to discover his secret. Report your findings to Gil Grisert.", progress = "Did Aderan's charm work?", completion = "You saw a nest, with hatchlings? Hmm... so our \"he\" is actually a \"she,\" eh?\n\nI guess that settles it. I suppose I wouldn't want to move a nest full of hatchlings just because of a new neighbor, either.\n\n<Gil favors Trapper Jethan with a mock glare.>\n\nI'm sure we'd get along just fine if ol' Jethan would stop trying to make a trophy of her.", sourceObjectiveStatus = "unverified-source-field" }
quests[11419] = { id = 11419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewfest Riding Rams", description = "If you show this hand stamp to Driz Tumblequick, the Ram Racing Apprentice, he'll allow you to purchase Brewfest riding rams.", sourceObjective = "Bring the \"Honorary Brewer\" Hand Stamp to Driz Tumblequick near the entrance to the Brewfest Grounds in Durotar.", progress = "Is that an \"Honorary Brewer\" stamp you've got on your hand?", completion = "Good job, {name}... you've won the trust of the festival's brewers, earning the right to purchase a Brewfest riding ram.", sourceObjectiveStatus = "unverified-source-field" }
quests[11420] = { id = 11420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path to Payback", description = "Two weeks ago our chief engineer got his hands on a vrykul harpoon gun - the same type of gun that the vrykul use to take down our ships. By studying that gun he managed to put together a comprehensive operation manual.\n\nUnfortunately he was abducted and taken north of here to Wyrmskull Village. We eventually did find him, but near death and without the manual. His dying words indicated that the manual was lost in the Utgarde Catacombs, located at the northwest end of Wyrmskull. Get me that manual!", sourceObjective = "Guard Captain Zorek at Valgarde in Howling Fjord wants you to recover the Harpoon Operation Manual.", progress = "Did you find the manual?", completion = "<Zorek flips through the manual.>\n\nHrm, interesting...\n\nAccording to the manual, the vrykul have a special tool that allows them to control the harpoon guns with deadly accuracy. It looks a bit like the wheel of one of our ships. Furthermore, it's portable and seems to plug into the harpoon guns like a key. We need to get our hands on one of those!", sourceObjectiveStatus = "unverified-source-field" }
quests[11421] = { id = 11421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Goes to 11...", description = "We must strike while the vrykul forces are in disarray! Take the harpoon control mechanism to Nifflevar and locate the northernmost harpoon building on the bluff side of the village.\n\nOnce there, commandeer one of the vrykul harpoon guns that are stationed on the building's deck. Use the harpoon gun to rain hell upon Wyrmskull Village! Destroy the longhouse, dockhouse, storage facility and any defenders that the vrykul may send at you!\n\nDo this and Daggercap Bay will become a much safer port!", sourceObjective = "Lieutenant Icehammer in the Howling Fjord wants you to destroy the Dragonflayer Longhouse, Dragonflayer Dockhouse, Dragonflayer Storage Facility and 8 Dragonflayer Defenders.\n\nReturn the Harpoon Control Mechanism to him once the task is complete.", progress = "Is Wyrmskull up in flames?", completion = "Excellent work, {name}! You took out a good chunk of their dragon riders and really pissed off their leadership.\n\nAre you ready to head back to Valgarde and report the good news to Zorek? If so, I've got a crazy idea!", sourceObjectiveStatus = "unverified-source-field" }
quests[11422] = { id = 11422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trident of the Son", description = "<From the scratches he makes in the rock, you see several symbols: a trident, a mur'ghoul, the sun, a wrecked ship, and a rough stick-figure of yourself.>\n\n<Puzzling out what the murloc is conveying takes a while. Obviously he wants you to get a trident from the Chillmere Coast, but the image of the sun is puzzling. That is until you realize he means his son.>\n\n<His son was changed into a mur'ghoul! He wants you to find him to the south near the wrecked ship and return with his trident.>", sourceObjective = "Old Icefin wants you to obtain Rotgill's Trident. Return it to him on the small island on the Chillmere Coast.", progress = "<One of Old Icefin's dead fish-like eyes studies you, clearly looking for signs of his son's trident.>", completion = "<Reaching out to take his son's trident from you, Old Icefin's hand shakes a little. Could it be that the aged murloc is grieving?>\n\n<Is that just extra moisture pooling at the base of his eye?>", sourceObjectiveStatus = "unverified-source-field" }
quests[11423] = { id = 11423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Enemy's Legacy", description = "As our armies march through Northrend, our enemies will not suffer mere defeat.  Their houses will burn, their corpses will be devoured by our plagues, all trace of their existence will be lost.\n\nThis worries me as a seeker of knowledge.  The eastern town of Nifflevar will soon be razed by our forces in Vengeance Landing.  The vrykul bard, Helgus, lived there and wrote three sagas: the Saga of the Twins, the Saga of the Winter Curse and the Saga of the Val'kyr.  Obtain them before Nifflevar is destroyed.", sourceObjective = "Go into Nifflevar, north of Ghostblade Post and look for the Saga of the Winter Curse, the Saga of the Val'kyr and the Saga of the Twins.", progress = "The scrolls, {name}?  Did you obtain them?", completion = "This is of tremendous value, {name}.  I must renew my efforts in salvaging and translating vrykul texts.\n\nDon't get me wrong.  Our enemies need to be destroyed... their ancient knowledge doesn't.", sourceObjectiveStatus = "unverified-source-field" }
quests[11424] = { id = 11424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shield Hill", description = "My work should be extremely easy in a time of war.  There ought to be usable body parts everywhere.\n\nIt's not that simple, though.  With these eggheads making all sorts of killer plagues and sending them to enemy towns, most of the material gets contaminated.\n\nThere is a place, though, where usable samples exist.  Shield Hill, south of here, is an ancient vrykul burial ground where the dead walk but are not afflicted with any plague - ours or the Lich King's.  Get me some bones, I'll pay ya well.", sourceObjective = "\"Hacksaw\" Jenny wants you to bring her 5 Ancient Vrykul Bones from the reanimated Vrykul in Shield Hill, south of New Agamand.", progress = "Got my bones then?", completion = "Hmmmmph... these will do for now.  There seems to be some oddness to them.\n\nI tell ya - I've handled body parts for years now and never have I had such a weird feeling in my stomach.  Anyway, a deal is a deal.  Here's your payment.", sourceObjectiveStatus = "unverified-source-field" }
quests[11426] = { id = 11426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Locating the Mechanism", description = "Don't worry, {name}; this is all going to lead to something big! HUGE! You're just going to have to trust me for now and do as I ask of you.\n\nWe need to get the mechanism mentioned in the manual for the next step of the plan. I have a strong suspicion that you'll find one on one of those vrykul that operate the harpoon guns in Wyrmskull Village. You'll find them on the east side of the village, on the docks by the longhouses.", sourceObjective = "Guard Captain Zorek at Valgarde in Howling Fjord wants you to bring him a Harpoon Control Mechanism.", progress = "Did you locate the mechanism?", completion = "Outstanding! Those overgrown apes will soon know what it means to mess with the Alliance!", sourceObjectiveStatus = "unverified-source-field" }
quests[11427] = { id = 11427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet Lieutenant Icehammer...", description = "Do you see those vrykul buildings on the bluffs to the northeast? The vrykul call that place Nifflevar. It's where most of their harpoon attacks on our frigates originate.\n\nWell guess what? The time for payback has come, {name}. I need you to take this harpoon control mechanism and meet up with Lieutenant Icehammer, who is hiding out in a vrykul building northwest of Nifflevar.\n\nWhen you're ready I'll place you on the back of one of our gryphons and zip you right to him!", sourceObjective = "Guard Captain Zorek wants you to take the Harpoon Control Mechanism to Lieutenant Icehammer stationed outside of Nifflevar.", progress = "What is this? Do I look like a babysitter?", completion = "<Lieutenant Icehammer takes the harpoon control mechanism from you.>\n\nAh, you come bearing gifts!", sourceObjectiveStatus = "unverified-source-field" }
quests[11428] = { id = 11428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeper Witherleaf", description = "You have been a great friend and ally to us, {name}. There is one more thing I must ask of you.\n\nYou have seen the corruption of the Twisted Glade and the beasts that dwell there. The blacksouled keepers will continue raising these abominations from the waters and soil of our glade unless we act against them.\n\nThe most powerful of the blacksouled keepers is known as Keeper Witherleaf. Slay him, {name}, and open the way for the redemption of the glade as you once redeemed my sisters.", sourceObjective = "Lurielle at the Frozen Glade wants you to kill Keeper Witherleaf.", progress = "Have you rid the Twisted Glade of Keeper Witherleaf?", completion = "My heart broke when I learned the keepers had turned against us. Once, we considered them our brothers and our closest friends.\n\nI grieve for the brothers and sisters we have lost, but without your help, there would be no hope for our future. You will always be welcome among us, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11429] = { id = 11429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drop It then Rock It!", description = "I'm not about to put the fate of this mission into the hands of some untested scrub.\n\nNow, if you want to prove to me that you've got what it takes to carry out this mission, you'll need to do what I tell you.\n\nTake this battle standard and head over to Baleheim, directly north of here. Once you're at Baleheim, find the center of town and drop our flag. Fight off any vrykul dirt bags that attempt to take down our beloved flag and return to me once you've established Alliance dominance!", sourceObjective = "Lieutenant Icehammer in the Howling Fjord wants you to place the Alliance Banner in Baleheim and then defend the banner against attackers.\n\nReturn to Lieutenant Icehammer with the Alliance Banner should you survive.", progress = "Still alive, I see. Clearly you're not trying hard enough.", completion = "For the Alliance! You're a strong one, {name}. Strong enough to crack some vrykul skull at Nifflevar.", sourceObjectiveStatus = "unverified-source-field" }
quests[11430] = { id = 11430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harpoon Master Yavus", description = "That was a fairly strong showing at Baleheim, {name}. Before you go off patting yourself on the back there's work to be done at Nifflevar.\n\nWe've located the vrykul responsible for the majority of the harpoon attacks on our frigates - goes by the name of Yavus. You'll find him in the main harpoon structure on the bluffs of Nifflevar, southeast of here.\n\nTrack him down and execute him for crimes against the Alliance!\n\nDo me proud, {name}!", sourceObjective = "Lieutenant Icehammer in the Howling Fjord wants you to slay Harpoon Master Yavus at Nifflevar.", progress = "Have you taken care of Yavus?", completion = "It'll take them a while to find a replacement for Yavus. Now is the perfect time to unleash Zorek's plan! While they're scurrying to regain control of Nifflevar, you're going to use their own harpoon guns against them!", sourceObjectiveStatus = "unverified-source-field" }
quests[11431] = { id = 11431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch the Wild Wolpertinger!", description = "Hey there! I'm a crazy dwarf! We dwarves believe when you get enough brew together, invisible creatures show up. In fact they are probably wandering around the Brewfest grounds right now! But you can only see them if you are really drunk.\n\nWe dwarves will come up with any excuse to drink.\n\nI bet you want a reason to drink too... So here it is, bring me 5 of those wolpertingers with this net I got from a really drunk dwarf.\n\nIf you can't see them, get some Synthebrew Goggles from me - almost as good!", sourceObjective = "The \"dwarf,\" Glodrak Huntsniper, has asked you to capture 5 Stunned Wolpertingers using the Wolpertinger Net. He mentioned that you must be intoxicated or wearing Synthebrew Goggles to see them.", progress = "Do you have something for me or are you just looking for another reason to get drunk?", completion = "What!  They really exist!   Now I feel bad for kicking that dwarf in the knee...\n\nI need a minute... and a drink...\n\n<He takes a drink from his stein.>\n\nI guess I could let you keep one... Proof that drunk dwarves (are there any other kind?) actually tell the truth.", sourceObjectiveStatus = "unverified-source-field" }
quests[11432] = { id = 11432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sleeping Giants", description = "I've overheard what you've had to say with Father Levariol. Allow me to suggest that he's not having you go far enough.\n\nYou must also deal with the vrykul that lie dormant in the Waking Halls beneath Gjalerbron!\n\nI have no doubt that the rituals involved with awakening them are the key to their downfall. Most likely the necrolords have some device that you can use to bring the vrykul out of their dormant state prematurely.\n\nSurely such a disruption will prove fatal to the vrykul.", sourceObjective = "Mage-Lieutenant Malister has tasked you with slaying 5 Dormant Vrykul. Return to him at Westguard Keep when you have done so.", completion = "You did what had to be done. Though some might consider it dishonorable to slay the helpless, in this case you would have been a fool to have done otherwise.\n\nAnd we certainly couldn't have just left them standing there to be ritually wakened, now could we?\n\nIt was a brave thing you did for all of us down in those catacombs, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11433] = { id = 11433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sleeping Giants", description = "I've overheard what you've had to say with Greatmother Ankha. With all due respect, she's not having you go far enough.\n\nYou must also deal with the vrykul that lie dormant in the Waking Halls beneath Gjalerbron!\n\nI have no doubt that the rituals involved with awakening them are the key to their downfall. Most likely the necrolords have some device that you can use to bring the vrykul out of their dormant state prematurely.\n\nSurely such a disruption will prove fatal to the vrykul.", sourceObjective = "Ahota Whitefrost has tasked you with slaying 5 Dormant Vrykul. Return to him at Camp Winterhoof when you have done so.", completion = "You did what had to be done. The unwise might consider it dishonorable to slay the helpless while they awaken, but in this case you would have been a fool to have done otherwise.\n\nAnd we certainly couldn't have just left them standing there to be ritually wakened, now could we?\n\nIt was a brave thing you did for all of us down in those catacombs, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11434] = { id = 11434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forgotten Treasure", description = "I've made my fortune by specializing in treasure that regular pirates don't appreciate: art, antiquities, collector's pieces.\n\nBlack Conrad's fleet sank south of here years ago.  All the gold and jewelry was picked clean by divers, but two ancient relics remain there.  One is a museum-quality Amani vase, the other is an eagle figurine.\n\nGo and retrieve them for me and I'll vouch for you with the other pirates.  I'll even throw in something to make your underwater adventure a bit more manageable.", sourceObjective = "Handsome Terry at Scalawag Point wants you to bring him 1 Amani Vase and 1 Eagle Figurine from the shipwreck to the south.", progress = "Did you obtain my relics, {name}?  Nobody gets by in this life on good looks alone... not even me!", completion = "We're going to go places together, {name}.  With my good looks and your... can-do attitude, we're sure to make a killing.", sourceObjectiveStatus = "unverified-source-field" }
quests[11436] = { id = 11436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let's Go Surfing Now", description = "Navigating the steep bluffs of Howling Fjord can be nerve-racking! I've come up with a solution to ease that burden by utilizing vrykul technology and dwarven ingenuity. With just a few adjustments and some fine tuning I've created Icehammer's harpoon controller! Of course it hasn't been tested, but that's what you're here for!\n\nTake the controller to the big gun in Nifflevar and use it to launch yourself into Valgarde. Report your victory to Zorek. Oh yea, you can keep the controller.", sourceObjective = "Use the large Vrykul Harpoon Gun in Nifflevar to launch yourself into Valgarde. Report your victory over the Vrykul to Guard Captain Zorek.", progress = "<Zorek raises an eyebrow at you.>", completion = "You are insane, {name}! What kind of degenerate would actually launch themselves from a harpoon gun as a method of travel?\n\nBut I guess you need to be a little crazy to pull off what you did up there on the bluffs! Fantastic work! We've gotten word that the Dragonflayer leader, Ingvar, is furious! Maybe one day you'll be ready to stomp his face into the dirt - in the name of our beloved Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[11439] = { id = 11439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Brigade Practice", description = "The brave dwarves of Kharanos can form a fire brigade in an instant, now that the Headless Horseman is around. Do you want to help?\n\nSouth of here, the mountaineers set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here.\n\nGood bye, {name}.  When you're done with fire brigade practice, please visit us again!", sourceObjective = "Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron.", progress = "Hello, {name}.  Have you been perfecting your fire fighting techniques?  Don't forget about the practice area to the south!", completion = "You're smudged with soot!  You must have been extinguishing fires!\n\nWell done!  As an honorary member of the Fire Brigade, I beg you to return here if ever the village needs you!", sourceObjectiveStatus = "unverified-source-field" }
quests[11440] = { id = 11440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Brigade Practice", description = "With the threat of the Headless Horseman looming, the peacekeepers have been diligent in forming a fire brigade when needed. Do you want to help?\n\nWest of here, toward the Exodar, the peacekeepers set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here.\n\nGood bye, {name}.  When you're done with fire brigade practice, please visit us again!", sourceObjective = "Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron.", progress = "Hello, {name}.  Have you been perfecting your fire fighting techniques?  Don't forget about the practice area to the west!", completion = "You're wet and smudged with soot!  You must have been extinguishing fires!\n\nWell done!  As an honorary member of the Fire Brigade, I beg you to return here if ever the village needs you!", sourceObjectiveStatus = "unverified-source-field" }
quests[11441] = { id = 11441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewfest!", description = "Speak to the Brewfest Organizer at the Brewfest Grounds outside of Ironforge and receive a free beer.", sourceObjective = "Speak to the Brewfest Organizer.", completion = "Ho ho! Come for your free beer?", sourceObjectiveStatus = "unverified-source-field" }
quests[11442] = { id = 11442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Brewfest!", completion = "Ho ho! Come for your free beer?" }
quests[11443] = { id = 11443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daggercap Divin'", description = "Hey... Uh... What's up? What are you doing down here?\n\nMe? Oh... Well, you see... I'm... Um... I'm trying to clean this place up! Orders from Keller himself! He says to me, \"Harry, I want you to put on a divin' bell and search the shipwrecks of Daggercap for OUR stuff...\"\n\nSay, maybe you could lend me a hand while you're down here. Throughout the bay here are all kinds of goodies, err, I mean supplies. Go out and bring me back whatever you find. Use this diving helm so you don't run out of air and die.", sourceObjective = "Harold Lagras at the bottom of Daggercap Bay wants you to recover 10 Valgarde Supply Crates.", progress = "Did you find those supplies?", completion = "Wow! You sure are efficient. Yep, well, just give me those crates. I'll need to document them and take inventory and some other stuff that you haven't been trained to deal with or understand. Don't worry; I'll be sure to let Keller know what a great job you did down here! Yep. Yea, you can leave now. Skedaddle!", sourceObjectiveStatus = "unverified-source-field" }
quests[11446] = { id = 11446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewfest!", description = "Speak to the Brewfest Organizer at the Brewfest Grounds outside of Orgrimmar and receive a free beer.", sourceObjective = "Speak to the Brewfest Organizer.", completion = "What?! A free beer? Yeah, yeah. I guess we said we'd do that this year.", sourceObjectiveStatus = "unverified-source-field" }
quests[11447] = { id = 11447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Brewfest!", completion = "What?! A free beer? Yeah, yeah. I guess we said we'd do that this year." }
quests[11448] = { id = 11448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Explorers' League Outpost", description = "It's all a bunch of cryptic nonsense! Even with this cipher I can't make heads or tails of these tablets. Admittedly, cryptography is not my strong point.\n\nYou'll need to take the cipher and tablets to our cryptographer, Stanwad. Unfortunately, I haven't heard from Stanwad in two weeks. He took a team of twenty scientists to the dig sites on the southeastern bluffs of the fjord and hasn't been heard from since. The best I can do is have McGoyver over there give you a lift with his flying machine.", sourceObjective = "Deliver McSorf's Bundle to Stanwad at the Explorers' League Outpost in Howling Fjord.", progress = "<Stanwad grumbles.>", completion = "<Stanwad takes the bundle from you and begins sorting the data.>\n\nWow. How many people did you say died to get this information?\n\n<Stanwad shakes his head.>\n\nYou'll be happy to know that what McSorf and his crew of bumbling imbeciles discovered is an ancient recipe for tundra stew. Did he not notice the icons of common vegetables and the pictograph of a humanoid mouth chompin' down on said veggies? You don't need a damned cipher to break this code!", sourceObjectiveStatus = "unverified-source-field" }
quests[11449] = { id = 11449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Training", description = "The deathstalkers have set up a fire training area outside the town.  We cannot afford further damage to the buildings of Brill - you should do your duty and train as a fire fighter.\n\nHead west past the graveyard, following the road. You'll find the training area there.", sourceObjective = "Toss Water Buckets on 5 fires, then speak with the Masked Orphan Matron in Brill.", progress = "Have you dowsed any fires, {name}?  The training area is west of Brill.", completion = "Well done, {name}.  Children, take a good look at this {class}.  Let him be a strong example to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11450] = { id = 11450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Training", description = "The guards have set up a fire training area outside the town.  We cannot allow the Horseman to destroy what we have worked so hard to rebuild - you should do your duty and train as a fire fighter.\n\nHead south through the gate to the crossroads. You'll find the training area there.", sourceObjective = "Toss Water Buckets on 5 fires, then speak with the Masked Orphan Matron in Falconwing Square.", completion = "Well done, {name}.  Children, take a good look at this {class}.  Let him be a fine example for you to follow.", sourceObjectiveStatus = "unverified-source-field" }
quests[11451] = { id = 11451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alicia's Poem", description = "Hi, I wrote a poem for my friend Caylee.  She likes to hang out with the Aldor in Shattrath City.  You know, in Outland?\n\nCould you take my poem to her?  My mommy says I'm too young to go to Shattrath City!", sourceObjective = "You have been asked to deliver Alicia's Poem to Caylee Dak in Shattrath City in Outland.", progress = "Oh, is that a poem?", completion = "What a touching poem, thank you!", sourceObjectiveStatus = "unverified-source-field" }
quests[11452] = { id = 11452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Slumbering King", description = "A sheaf of parchment drops from the still hand of the overlord. Upon it you can discern the outline of the rituals that are taking place in the catacombs below.\n\nHowever, it appears that the queen of the vrykul, Angerboda, is having difficulty awakening King Ymiron. The ritual is taking place within the large chamber, known as the Winter's Terrace, on the north end of Gjalerbron.\n\nIf you hurry, you may be able to stop her before it is too late.", sourceObjective = "Defeat Queen Angerboda and stop the ritual to awaken King Ymiron. Should you manage to do so, return to Westguard Keep and report your success to Captain Adams.", completion = "I'm not sure that I like the sound of that one bit! The Lich King absconding with Ymiron can only mean trouble. Unfortunate that you weren't able to kill him along with his queen.\n\nStill, you've put a huge dent in their plans and bought us the valuable time that we need.\n\nAnd who knows, with the way you get around, you'll likely run into King Ymiron again. I'm sure that he won't fare so well the next time you meet.", sourceObjectiveStatus = "unverified-source-field" }
quests[11453] = { id = 11453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Slumbering King", description = "A sheaf of parchment drops from the still hand of the overlord. Upon it you can discern the outline of the rituals that are taking place in the catacombs below.\n\nHowever, it appears that the queen of the vrykul, Angerboda, is having difficulty awakening King Ymiron. The ritual is taking place within the large chamber, known as the Winter's Terrace, on the north end of Gjalerbron.\n\nIf you hurry, you may be able to stop her before it is too late.", sourceObjective = "Defeat Queen Angerboda and stop the ritual to awaken King Ymiron. Should you manage to do so, return to Camp Winterhoof and report your success to Chieftain Ashtotem.", completion = "I'm not sure that I like the sound of that one bit! The Lich King absconding with Ymiron can only mean trouble. Unfortunate that you weren't able to kill him along with his queen.\n\nStill, you've put a huge dent in their plans and bought us the valuable time that we need.\n\nAnd who knows, with the way you get around, you'll likely run into King Ymiron again. I'm sure that he won't fare so well the next time you meet.", sourceObjectiveStatus = "unverified-source-field" }
quests[11454] = { id = 11454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek the Saboteurs", description = "This scrap of paper seems to have been left behind accidentally by the Dark Iron invaders.\n\nWhile the plans are complicated and written in some form of coded Dwarvish, the signature at the end - \"Coren Direbrew\" - is clear enough, as is mention of the Grim Guzzler deep within Blackrock Depths. You should seek out the instigator and put an end to these raids.", sourceObjective = "Find Coren Direbrew in the Grim Guzzler within Blackrock Depths.", sourceObjectiveStatus = "unverified-source-field" }
quests[11455] = { id = 11455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fragrance of Money", description = "Us pirates are known for many things, but hygiene isn't one of them.  Most pirate ships be carrying five or six times as many rats as people.\n\nIt's no wonder all the bears on this island caught the rabies soon after we moved in.  Long story short, the boss wants 'em all dead.\n\nIt just so happens I know a recipe for a bear musk fragrance popular among Stormwind nobles.  We kill the bears and sell the musk.  I see a fine business opportunity for us here.  What say ye?", sourceObjective = "Handsome Terry at Scalawag Point in Howling Fjord wants you to obtain 4 Bear Musk from the Rabid Brown Bears in the surrounding area.", progress = "Ye got the bear musk for me, matey?", completion = "Excellent work!  It might not be quite as daring as plundering the high seas, but I'd be a darned son of a deckswabber if I passed on this opportunity.", sourceObjectiveStatus = "unverified-source-field" }
quests[11456] = { id = 11456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding the Survivors", description = "We tuskarr rely mostly on our fish catch for sustenance.  In times of great need, however, we will on occasion hunt land animals.\n\nThe nearby village of Iskaal was recently attacked by pirates and the survivors just keep pouring in.\n\nOur catch has been modest this week, but there are many shoveltusk on the island and their meat is plentiful.\n\nAid my people by hunting these great beasts and obtaining their meat.", sourceObjective = "Elder Atuik at Kamagua in Howling Fjord wants you to obtain 6 pieces of Island Shoveltusk Meat from Island Shoveltusk in the Isle of Spears.", progress = "Have you obtained the meat we need?", completion = "I thank you, {name}.  My people are in a time of great need.", sourceObjectiveStatus = "unverified-source-field" }
quests[11457] = { id = 11457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arming Kamagua", description = "Issliruk, the spirit of war, is depicted as a silver eagle by my people.  Our stories tell of how Issliruk fought against a hundred worgs to save his young.\n\nIt is time for us, too, to fight against our foes to save our brethren.  We will need to craft new weapons.  The horns of the frostwing chimaera that make their home in the snowy parts of the island are sharp and are easily crafted into spear tips.  Bring me the best of these horns that you can find.", sourceObjective = "Elder Atuik wants you to obtain 3 Chimaera Horns.", progress = "It's good to see you again, {race}.", completion = "You continue to prove your worth as an ally, {name}.  Your actions will not be forgotten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11458] = { id = 11458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avenge Iskaal", description = "The totem of Issliruk is ready, {name}, and for that I thank you.  We must cast our peaceful ways for the time being and strike at those who've attacked our land and our kin.\n\nThe pirate slavers that raided Iskaal have lost their minds and slaughtered all their captives.  Go to Iskaal, to the east of here and do what must must be done.  Take this horn and call on my brethren should you need assistance.", sourceObjective = "Elder Atuik wants you to go to Iskaal and slay 8 Northsea Slavers. Use the Horn of Kamagua should you need assistance.", progress = "Have you done what I asked of you, {name}?", completion = "You are a formidable ally, {name}.  My people will forever be in your debt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11459] = { id = 11459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeh'gehn Sez", description = "Is like dis, mon.  Ye be wantin' me 'elp spotting some craven bag-o-wire been cardin' da crew?\n\nYe gotta bring me a croaker, matey.  Aft I an' I show ye who da blaggard be, mon.  Nah, nah, croaker show ye.  Ye'll ku fer yerself with yer own deadlights, yahso.\n\nBring us a carver yahso too, 'atsteppa.  Galang, bucko.", sourceObjective = "Return to Handsome Terry to decipher what Zeh'gehn asked of you.", completion = "You didn't understand a thing Zeh'gehn said?  Well, of course not.\n\nLet's see then.", sourceObjectiveStatus = "unverified-source-field" }
quests[11460] = { id = 11460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trust is Earned", description = "The first and most important factor in falconry is the bond between the falconer and <his/her> bird. Trust must be earned by the master!\n\n<Hidalgo points to the falcons in the cage at his feet.>\n\nIf you are to earn their trust you will first need to fill their bellies.\n\nThe fjord rock falcon, as these birds are known, primarily eat grubs. Throughout the fjord you will find loose rocks that serve as breeding grounds for these grubs. Find a grub and return here to feed the falcons in the cage.", sourceObjective = "Hidalgo at the Explorers' League Outpost in the Howling Fjord wants you to find a Fjord Grub and feed it to one of the falcons in the cage by his feet.", progress = "This is an important exercise, {name}. If you are to become a falconer you must learn how to feed your bird.", completion = "Yes, {name}. I can see the bond of companionship forming. She has accepted you as master.", sourceObjectiveStatus = "unverified-source-field" }
quests[11462] = { id = 11462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handsome Terry", description = "Your people paid me good money to infiltrate the Northsea Freebooters and get your foot in the door.\n\nI talked you up to a fellow in Scalawag Point called Handsome Terry.  I told him you come highly recommended.\n\nPut your disguise on and go see him.  Here comes someone to take you there.\n\nYou're going to have to prove yourself a bit before they introduce you to their higher ups.  But that's all up to you.  Remember, {name}, once you're inside you're on your own!", sourceObjective = "Don the Pirate Disguise and speak to Handsome Terry inside Scalawag point.\n\nProvided item:", sourceObjectiveStatus = "unverified-source-field" }
quests[11463] = { id = 11463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pirates of the North Seas", description = "The past few weeks have seen an increase in pirate attacks against our supply ships.  We've hired a goblin spy to pave the way for one of our agents to infiltrate the suspected pirates.\n\nThis group of Northsea Freebooters operates out of Scalawag Point, on Garvan's Reef.  We don't know much about them, but we do know that Sylvanas wants their leader's head.\n\nYou come very highly recommended, {name}.  If you take on this task, we can keep our military focused against Arthas' forces.  Are you up to it?", sourceObjective = "Find Grezzix Spindlesnap on the northern end of Garvan's Reef off of the Southwestern coast of Howling Fjord.The past few weeks have seen an increase in pirate attacks against our supply ships. We've hired a goblin spy to pave the way for one of our agents to infiltrate the suspected pirates.\n\nThis group of Northsea Freebooters operates out of Scalawag Point, on Garvan's Reef. We don't know much about them, but we do know that Sylvanas wants their leader's head.\n\nYou come very highly recommended, {name}. If you take on this task, we can keep our military focused against Arthas' forces. Are you up to it?", sourceObjectiveStatus = "unverified-source-field" }
quests[11464] = { id = 11464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gambling Debt", description = "I heard you did a little work for Terry.  I was hoping someone reliable would show up around these parts.\n\nSee, pirates love to gamble.  They, however, do not love to pay their gambling debt.\n\nIf you're interested in collecting some coin on my behalf, I'd be willing to give you a cut.\n\nLet's start you out with an easy one.  \"Silvermoon\" Harry's a bit of an eccentric, keeps all sorts of expensive blood elf knickknacks inside his tent - yet when I see him he always pretends to be broke.  Get my gold.", sourceObjective = "Taruk at Scalawag Point wants you to collect \"Silvermoon\" Harry's Debt.", progress = "You're back.  Did you get what's owed to me?", completion = "A job well done.  Here's your cut, {name}.  There's more where this came from.\n\nThere's no shortage of deadbeat pirates on this island.", sourceObjectiveStatus = "unverified-source-field" }
quests[11465] = { id = 11465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ransacked Caravan", description = "I was leading a caravan here from Valgarde that was attacked by Dragonflayers. I was the only survivor of that ambush. Unfortunately, I couldn't make it back here with the cargo of fjord turkeys. This is the perfect opportunity for you to get your feet wet with your rock falcon.\n\n<Hidalgo hands you a cage.>\n\nTake this falcon cage and head west down the road leading out of this camp. Use the falcon to capture the loose turkeys and return here when you've gathered enough.\n\nRemember to feed the falcon!", sourceObjective = "Hidalgo at the Explorers' League Outpost in the Howling Fjord wants you to use the Trained Rock Falcon to recover 5 Fjord Turkeys.\n\nReturn to Hidalgo with the cage once you have completed this task.", progress = "Your falcon must be constantly fed or else it will eat the prey that you are sending it to kill.", completion = "Clever fiends. And patient too! We need to stop underestimating our enemy. Those vrykul are deadly hunters!\n\nRegardless, mission accomplished. Perhaps it is time for you to hunt something a bit more elusive than a fat turkey, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[11466] = { id = 11466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jack Likes His Drink", description = "Our next customer,  Jack Adams, won't be the pushover that Harry was.  He spends all day drinking with his friends, tough pirates all of them.  Let's not use force this time, could get ugly.\n\nSee if you can use his drinking habit to your advantage.  There's only so much alcohol someone can handle before passing out.\n\nMaybe one of the bar wenches will be of assistance.  Once he's out, see if you can slip your hand into his pocket and get what's mine.", sourceObjective = "Taruk at Scalawag Point in Howling Fjord wants you to collect Jack Adams' Debt.", progress = "Did you get what's mine, {name}?", completion = "I'm impressed, {name}.  And I'm not the type who's easily impressed.", sourceObjectiveStatus = "unverified-source-field" }
quests[11467] = { id = 11467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dead Man's Debt", description = "You might've heard of Black Conrad, he's a famous pirate around these parts.\n\nWell, he had a thing for gambling on my fights.  He had a thing for not paying, too.\n\nI'd love to collect, but trouble is... he's dead.\n\nI was about ready to write the whole thing off, when I came across this...\n\n<Taruk unfolds a map of the Isle of Spears with an X on a northeastern plateau.>\n\nHe hid his treasure on tuskarr land.  I want you to get it.  I'll be damned if I let that bilge sucker get away without paying.", sourceObjective = "Taruk at Scalawag Point wants you to search for Black Conrad's Treasure on the plateau in the northeastern end of the Isle of Spears, just north of Iskaal.", progress = "Did you find the treasure, {name}?", completion = "I'll take the gold, as it is what Conrad owed me.  The rest is for you to keep.\n\nIf you're ever in need of something more permanent, I'm sure I could arrange for something.  In the meantime, may the wind blow strong in your sail, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[11468] = { id = 11468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falcon Versus Hawk", description = "Do you feel the closeness, {name}? Surely you feel a true bond forming between you and your falcon. Would you believe me if I told you that when the time is right you'll be able to see through the eyes of your bird? Aye, it is the ultimate level of falconry.\n\nBut first you must hunt more! The bird must hone and quicken its reflexes. Send it against a more formidable opponent! The fjord hawks of the region make the tops of the trees around us their homes. They shall be your next target!", sourceObjective = "Hidalgo at the Explorers' League Outpost in the Howling Fjord wants you to use your Trained Rock Falcon to capture 10 Fjord Hawks.\n\nReturn to Hidalgo with the cage when you have completed this task.", progress = "Your falcon must be constantly fed or else it will eat the prey you are sending it to kill.", completion = "Aye, the hawks are very territorial and often travel in packs. I suppose I could have told you that before I sent you out into the field.", sourceObjectiveStatus = "unverified-source-field" }
quests[11469] = { id = 11469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swabbin' Soap", description = "Yeah, I got to get the deck swabbed spotless afore Mad Jonah comes 'round. An' I ain't gonna do it on my hands and knees neither!\n\nProblem is, we're all outa soap. That's more your problem than mine though, mate. Being the newbie 'round here, I gots a special trip for ya to make.\n\nUp on the northwest coast of this island, there's a whole mess o' sea lions. Amongst the nearby ice floes you'll find the alpha bull, Big Roy. Bring me back his blubber and I'll magic-up the best soap ya ever seen!", sourceObjective = "Scuttle Frostprow wants you to obtain Big Roy's Blubber as the main ingredient for her magic swabbin' soap. Return to her on the eastern pirate ship at Scalawag Point when you have it.", progress = "Where's that blubber? An' don't try to tell me he ain't got none either.\n\nThat Big Roy's so damned big it's a wonder he can still galumph around!", completion = "Ew, that's a stink if I ever smelled one!\n\nGo on now, put it down right here. I'll cast my spell and she'll be swabbin' soap for sure!", sourceObjectiveStatus = "unverified-source-field" }
quests[11470] = { id = 11470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There Exists No Honor Among Birds", description = "You are most definitely ready for the next step in falconry, {name}.\n\nTake your trained falcon east of here, to the vrykul hawk roost near the Stonewall Lift. From the roost you will send out your falcon to steal the eggs of the hawks. Their nests will be located in remote areas of the cliff walls surrounding the roost. Locate those nests and use your falcon to scavenge for the eggs!\n\nBeware the fjord hawk matriarchs, {name}. Should you come under attack, use your falcon's escape and soar abilities to flee!", sourceObjective = "Hidalgo at the Explorers' League Outpost in the Howling Fjord wants you to use your Trained Rock Falcon to capture 8 Fjord Hawk Eggs.\n\nReturn to Hidalgo with the cage when you have completed this task.", progress = "You are in control now, {name}. Guide your falcon and bring me those eggs.", completion = "Bravo, {name}! Bravo! The bond of kinship between you and your falcon is strong! Perhaps you can run some reconnaissance missions against the vrykul in the not-too-distant future?", sourceObjectiveStatus = "unverified-source-field" }
quests[11471] = { id = 11471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Jig is Up", description = "I know why you're here, {name}.  You've been sent to kill our leader, Jonah Sterling.\n\nI'd like to offer my help.  Jonah's leadership threatens our operation.\n\nAttacking the Horde and the Alliance fleets simultaneously?  Suicidal.  Trying to sell the tuskarr as slaves when they die days after leaving this climate?  Disastrous.\n\nJonah's hideout is located inside a cave west of here.  Bring me his spyglass as proof of the deed and my first action as leader will be to end all attacks against your allies.", sourceObjective = "Annie Bonn at Scalawag Point wants you to bring her Jonah Sterling's Spyglass.", progress = "Well, {name}.  Did you get Jonah's spyglass?\n\nI can't just take your word for the assassination, you know?  I am a pirate after all.", completion = "Jonah Sterling's days are finally over!  He never thought this \"wench\" would make it.\n\nAs word of Jonah's death spreads among the pirates I will consolidate my leadership.  Your allies won't get any more trouble from my crew, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11472] = { id = 11472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Way to His Heart...", description = "The Northsea Pirates slaughtered the isles' alpha sea lion bull, Big Roy. They made soap from him to clean the decks of their ships!\n\n<Anuniaq sighs.>\n\nNow the sea lions won't mate. Help me to repopulate their numbers.\n\nThe reef bulls can be found at the Twin Shores to the southeast. They crave the tasty reef fish that can be found on the east and west sides of the isles.\n\nTake this net and gather enough fish, at least a dozen -- maybe more, to lure a bull across the strait to a reef cow.", sourceObjective = "Toss Tasty Reef Fish at a Reef Bull to lead it to a Reef Cow. Once you have helped the two to find true love, return to Anuniaq at Kamagua.", progress = "Have you helped a reef bull and cow to get to know each other?", completion = "This is good news! Now more bulls will swim across the strait to mate with the cows. Soon there will be plenty of new reef pups on the isles.\n\nThank you, {race}. Whatever you might have done in the past, know that you have helped with Kamagua's future!\n\nWe'll have to keep up the good work if we're going to see to it that their numbers are replenished. Please come back again tomorrow so that we can help another couple find each other.", sourceObjectiveStatus = "unverified-source-field" }
quests[11473] = { id = 11473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Traitor Among Us", description = "Our second in command, Annie Bonn, has been acting rather paranoid as of late.  She seems sure we have an infiltrator in our ranks, can ye believe it?\n\nAnyhow, we have a foolproof way of uncovering rats around these parts.  See, good ole' Zeh'gehn over here happens to be an authentic witch doctor.  His family hails all the way from Zul... something or other.\n\nGo let him know that we're in need of his divination skills.  I must warn ye, {name}, only one or two of us can understand anything Zeh'gehn says.", sourceObjective = "Speak to Zeh'gehn at Scalawag Post.", completion = "Ku here, mate.  Ye come fe see I an' I, aye?", sourceObjectiveStatus = "unverified-source-field" }
quests[11474] = { id = 11474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Problems on the High Bluff", description = "As usual, the real work is left up to me and my crew. Thankfully McSorf's team didn't die for nothin'. The cipher they recovered will help us crack the stuff we've found up here - that is if we can ever get back to it! Damned iron dwarves have sprung up like leaks all over the place and are now attemptin' to bury the sites! Can you believe it? Bastards want to bury our finds!\n\nAnyhow, talk to Walt over yonder. He'll get you started.", sourceObjective = "Speak with Walt.", completion = "Over half our team is dead or missing, junior. This is our last stand up here on the high bluffs. Those damned iron dwarves pushed us out of both Ivald's Ruin and Baelgun's. Now I've got a plan to get us back inside before they bury up all our goodies and we lose that data forever.", sourceObjectiveStatus = "unverified-source-field" }
quests[11475] = { id = 11475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tools to Get the Job Done", description = "I've been studying this deactivated construct for days, {name}. I think I can create a reasonable facsimile of the golem that would have room inside to fit one passenger. The idea being that it would fool those iron dwarves and allow us to get inside Baelgun's.\n\nNow I'm not gonna be able to make anything with a hammer and poker. I need my tools! Unfortunately I left those behind at Ivald's Ruin when the iron dwarves first attacked. Get me my tools!\n\nIvald's Ruin is located far to the northeast.", sourceObjective = "Walt at the Explorers' League Outpost in the Howling Fjord wants you to recover his Building Tools.", progress = "Step 1: Get Walt his tools.", completion = "Now that I've got my tools, the building can begin. Well, as soon as I have some materials. You'll be getting those for me next.", sourceObjectiveStatus = "unverified-source-field" }
quests[11476] = { id = 11476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Carver and a Croaker", description = "Some of the pirates around here... we have our own special way of talking.  Zeh'gehn has... many different special ways of talking... all mixed together.\n\nFrom what I can tell he wants a frog and a knife.\n\n\"Silvermoon\" Harry might have a knife on the cheap.  There's frogs all over town, just grab one and bring it to him along with the knife.\n\nI'd hate to be in the poor critter's shoes, if you know what I mean.", sourceObjective = "Get a Shiny Knife from \"Silvermoon\" Harry and capture a Scalawag Frog. Bring these to Zeh'Gehn at Scalawag Point.", progress = "Ye get the croaker and carver, mon?", completion = "Much obliged, bucko.  Croaker's lookin' real cris!", sourceObjectiveStatus = "unverified-source-field" }
quests[11477] = { id = 11477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of My Element?", description = "Keep it down, {race}. These iron dwarves are quick on the trigger. Now don't let the activities down in the dig fool you. Those steel-skinned abominations aren't digging anything up! No sir - on the contrary - they're burying the site! For whatever whacked out reason, they don't want anyone finding this place.\n\nWhat kind of dwarf buries ancient relics and dig sites? I'll tell you what kind: the kind you kill with reckless abandon! Get in there and take 'em out!", sourceObjective = "Donny at Ivald's Ruin in the Howling Fjord wants you to kill 10 Iron Rune Destroyers, 5 Iron Rune Laborers and 2 Iron Rune Sages.", progress = "You'll need to kill until you've had your fill.", completion = "Good job, {name}. That'll slow down the burial process a little.", sourceObjectiveStatus = "unverified-source-field" }
quests[11478] = { id = 11478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Outpost Over Yonder...", description = "I see that you haven't visited my brothers at the Explorers' League Outpost south of here. Why don't you do Donny a favor and deliver this message to Stanwad. He'll be interested to hear about the activities of the iron dwarves up here.\n\nLike I said, mount up and start heading south. You'll see the outpost right before you get to Baelgun's.", sourceObjective = "Deliver Donny's Letter to Stanwad at the Explorers' League Outpost.", progress = "News from Donny?", completion = "Yea, this isn't anything we don't already know. At least Donny's still alive.", sourceObjectiveStatus = "unverified-source-field" }
quests[11479] = { id = 11479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Crowleg\" Dan", description = "Croaker's spoken, matey. \"Crowleg\" Dan's on da ship yonder.\n\nBest go trace that blaggard, mon.  Show'im dis set's not fe be crossed.  Gaan back fe Terry when ye keelhaul 'is behind.", sourceObjective = "Confront \"Crowleg\" Dan, who is in one of the ships at Scalawag Point. Speak to Handsome Terry when you've completed this task.", progress = "I can't believe it was Dan.  Did you take care of it yet?", completion = "That's some sad news.  Dan was me old friend... AND he owed me money.  Either way, if he was working with the Southsea mongrels he got what he deserved.\n\nAs for you, my friend.  You're on your way up.  Literally.", sourceObjectiveStatus = "unverified-source-field" }
quests[11480] = { id = 11480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet Number Two", description = "All the good work you've done for us hasn't gone unnoticed, {name}.  Our second in command, the delightful Annie Bonn, is incredibly impressed with what you've done so far and wants to meet you.", sourceObjective = "Speak to Annie Bonn at Scalawag Point.", completion = "Well, well, well.  If it isn't {name}.  You show up at Scalawag point, no one's heard of you except some goblin friend of that half-wit Terry.\n\nLet's just say I'm a bit... skeptical... of your intentions here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11481] = { id = 11481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crisis at the Sunwell", description = "By the naaru, I thank you, {race}, for your efforts.\n\nOur work is far from finished, however, and I must request that you undertake a critical mission - one as important as any I've issued.\n\nOur forces are spread thinly. To compound the strain, we've had to dispatch a contingent to Azeroth to investigate developments at the Sunwell Plateau.\n\nYou are needed there, {name}. Report to Larethor. Tell him that I wish we could spare more men.", sourceObjective = "Adyen the Lightwarden on the Aldor Rise in Shattrath City has requested that you travel to Sunwell Plateau and speak with Larethor.", completion = "Another soldier from Shattrath? A welcome sight!\n\nWish there were more of you, but we'll make due with what we have. Whatever's going on out here won't wait for us to make ready.\n\nHave a look around, {class}. There's much that needs doing. Pitch in and do your share.\n\nOh, yeah, and don't go tauntin' the cryers - err, Scryers. Looks like we're in this thing together....", sourceObjectiveStatus = "unverified-source-field" }
quests[11482] = { id = 11482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duty Calls", description = "Hear me, {race}.\n\nDuty requires that you return to Azeroth. Every able person is to report to the Sunwell Plateau immediately.\n\nI'm afraid I have no more information to share, except this:\n\nYou'll be joining forces with the Aldor for this mission. Speak with a draenei by the name of Larethor when you arrive.\n\nApparently, the situation calls for us to set our differences aside and join forces.\n\nPrepare yourself, friend. This sounds serious.", sourceObjective = "Dathris Sunstriker on Scryer's Tier in Shattrath City has insisted that you travel to Azeroth at once and report to Larethor at the Sunwell.", completion = "Welcome to Sunwell Plateau, cryer - What's that? Oh Scryer, yes of course. Isn't that what I said?\n\nWell, now, let's get a few things straight. There's some serious business going on behind those walls and it's in the interest of both of our people to address it. And since neither of us have the forces to go it alone, we're going to work - TOGETHER. Got that?\n\nNow let's get started, shall we?", sourceObjectiveStatus = "unverified-source-field" }
quests[11483] = { id = 11483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Can Rebuild It", description = "Tools? Check. Materials? Negative.\n\nIf we're going to build this thing, you're going to have to get me the materials.\n\nFirst things first, {name}. For the skeletal structure I'm going to need a large barrel from Nifflevar, some dark iron ingots from Valgarde, and industrial strength rope from Baleheim.\n\nNifflevar and Baleheim are vrykul towns northwest of here. Valgarde is located in Daggercap Bay, also to the northwest. Speak with McGoyver to get the ingots. He'll fly you back here once you're all done.", sourceObjective = "Walt at the Explorers' League Outpost in the Howling Fjord wants you to bring him a Large Barrel, Industrial Strength Rope and Dark Iron Ingots.", progress = "Have you got the infrastructure materials?", completion = "Excellent. These combined with the skin will make for a flawless clone of the constructs the iron dwarves use.", sourceObjectiveStatus = "unverified-source-field" }
quests[11484] = { id = 11484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Have the Technology", description = "While the infrastructure for a piece of machinery like this is important, we can't underestimate the appearance of the construct. If we're to fool the iron dwarves the clone must be exact!\n\nI can make this happen.\n\nBring me a pristine shoveltusk hide from the shoveltusk of this region and steel ribbing from vrykul in Nifflevar or Baleheim to the northwest.", sourceObjective = "Walt at the Explorers' League Outpost in the Howling Fjord wants you to bring him a Pristine Shoveltusk Hide and Steel Ribbing.", progress = "We'll be back collecting our relics in no time!", completion = "I'll have the construct all ready to go as soon as the infrastructure is complete.", sourceObjectiveStatus = "unverified-source-field" }
quests[11485] = { id = 11485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Rune Constructs and You: Rocket Jumping", description = "Alright, {name}; the time has come for you to climb inside this thing and learn how to use its basic abilities. When you're ready, get on the work bench and I'll get you situated inside the construct.\n\nYour first lesson is going to be using the construct's transportation system. You'll notice that the iron dwarves have set up special rune carvings around the dig site. Their constructs use those rune carvings to power up and fly from point to point. Try it with the rune carving I built here.", sourceObjective = "Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct's Rocket Jump ability at Walt's Iron Rune Carving.\n\nDismiss your construct by dismissing it from the pet window once you have completed the quest.", progress = "Don't take any lip from these naysayers!", completion = "You're almost ready to take this work of art into the field, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11488] = { id = 11488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magisters' Terrace", description = "Welcome to the Sunwell, {class}. Get yourself settled in and contribute however you can - there's much to do!\n\nMe? Yes, I have a little something that needs doing, but I'm not sure you're up to the task.\n\nWe've had a contact embedded in Magisters' Terrace gathering intelligence for us. He's recently failed to report and I'm growing concerned.\n\nThe terrace is just up the rise to the east. The information he was collecting is vital to our mission.\n\nThink you can handle it, {race}?", sourceObjective = "Exarch Larethor at the Shattered Sun Staging Area wants you to search Magisters' Terrace and find Tyrith, a blood elf spy.", completion = "...Come closer, {race}... Listen carefully to my words....", sourceObjectiveStatus = "unverified-source-field" }
quests[11489] = { id = 11489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Rune Constructs and You: Collecting Data", description = "The most important part of your job while controlling the construct is the collection of data. I've placed an iron dwarf relic in the cart over yonder. It's the floating, lightning infused crystal.\n\nGet on the work bench and I'll put you back in the construct. Once you're back in the driver's seat, use the construct's data collection ability to pick up the test data.", sourceObjective = "Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct's Collect Data ability while standing near the Iron Dwarf Relic.\n\nDismiss your construct by dismissing it from the pet window once you have completed the quest.", progress = "Fits like a glove, don't it?", completion = "Perfect! Works like a charm!", sourceObjectiveStatus = "unverified-source-field" }
quests[11490] = { id = 11490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scryer's Scryer", description = "Go to the terrace... use the orb.\n\n<Tyrith gasps for breath.>\n\nHurry... they must be stopped... before they can....\n\n<Tyrith dies.>", sourceObjective = "Tyrith wants you to use the orb on the balcony in Magisters' Terrace.", progress = "Go and peer into the orb, mortal.", completion = "I consider it to be no coincidence that our paths cross this day.\n\nI sense the tendrils of destiny....", sourceObjectiveStatus = "unverified-source-field" }
quests[11491] = { id = 11491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Rune Constructs and You: The Bluff", description = "You always gotta have a contingency plan in case your main plan backfires! That's why I've built in some anti-intelligence systems into the construct.\n\nYour shiny new ride might rouse some suspicion while you're at Baelgun's excavation site. That's what your bluff ability is for! Just use that any time you're confronted and you'll be safe from harm.\n\nTest it out on Lebronski by walking on his rug. Once he starts huffin' and puffin', use the bluff!\n\nGet on the work bench when you're ready to begin.", sourceObjective = "Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct's Bluff ability on Lebronski after you've walked on his rug.\n\nDismiss your construct by dismissing it from the pet window once you have completed the quest.", progress = "Don't worry about him, {name}. He'll get over it...", completion = "You showed him! Now it's time to put you in the field.\n\nFeeling confident, I hope...", sourceObjectiveStatus = "unverified-source-field" }
quests[11492] = { id = 11492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hard to Kill", description = "Welcome to the Sunwell, mortals. Your arrival is indeed timely.\n\nAs you've now witnessed, the Legion forces work tirelessly, manipulating the Sunwell's power to achieve their malevolent ends.\n\nKael'thas has risen from the ashes of defeat and once more leads them in their efforts. Find him, mortals. He must again be stopped.\n\nOther, equally urgent matters require my immediate attention. I shall leave Kael's fate to you. Do not fail.\n\nWith luck, we shall speak again.", sourceObjective = "Kalecgos has asked you to defeat Kael'thas in Magisters' Terrace. You are to take Kael's head and report back to Larethor at the Shattered Sun Staging Area.", progress = "Well, {class}, I must admit, I wasn't sure I'd see you again.\n\nWhat news do you bring?", completion = "<Larethor listens intently as you explain your deeds in Magisters' Terrace.>\n\nTyrith will be missed - good man, that one. Thanks to you though, his death wasn't in vain.\n\nI've underestimated you, {race}. Please, accept this on behalf of the Sunwell Offensive - a gift worthy of a hero such as yourself.", sourceObjectiveStatus = "unverified-source-field" }
quests[11494] = { id = 11494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightning Infused Relics", description = "Your construct is ready to go. All abilities have been given a once over and I've programmed the machine to both comprehend and speak the language of the titans.\n\nTake the construct to Baelgun's Excavation Site, due south of here, and collect data from the lightning infused relics that litter the site. Remember to bluff any iron dwarves that suspect your construct to be a fake. And don't forget about rocket jumping from rune to rune to get around in there!\n\nGet on the table when you're ready!", sourceObjective = "Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct's Collect Data ability to collect 15 sets of Iron Rune Data.\n\nDismiss your construct by dismissing it from the pet window once you have completed the quest.", completion = "And once again Walt proves that he is indeed the top dwarf! What do you think of my construct now, Lebronski!\n\nThank you, {name}. This data will undoubtedly prove to be invaluable - as soon as I figure out how to get it out of the construct.", sourceObjectiveStatus = "unverified-source-field" }
quests[11495] = { id = 11495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Delicate Sound of Thunder", description = "The cavern that we opened at Baelgun's was the one place that most steered clear of... Can't say I blame 'em. The sound of thunder shot out of that cave, {name}! Loud, booming thunder!\n\nI think near the end, it was abandoned by all. Bad, bad things happened to any that went in to explore - most never coming back.\n\nI want you to check that cave out while you're at Baelgun's. Explore around the titan statue inside and report back with your findings.", sourceObjective = "Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct to explore the thundering cave at Baelgun's Excavation Site.\n\nDismiss your construct by dismissing it from the pet window once you have completed the quest.", progress = "Any luck?", completion = "Incredible! What could those iron menaces be up to? What are they doing in the Storm Peaks? And what is this Loken!? I'll forward this information to our central base of operations in the Dragonblight, {name}. I'll also let 'em know that you were invaluable in the acquisition of said info.", sourceObjectiveStatus = "unverified-source-field" }
quests[11496] = { id = 11496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sanctum Wards", description = "Our first priority is to capture the Sun's Reach Sanctum.  Once we've secured it, we'll be able to use its energy to open a portal from Shattrath.\n\nThe sanctum is overrun with the Wretched - former blood elves who've devolved into mindless husks of their former selves.  Its defenses would've normally prevented this intrusion, but the Wretched have stolen the power sources from the protective wards.\n\nHunt down the Wretched and get the mana remnants they carry.  Use them to energize the sanctum wards.", sourceObjective = "Captain Theris Dawnhearth at the Shattered Sun Staging Area wants you to obtain 4 Mana Remnants from Wretched Fiends and Wretched Devourers and use them to energize one of the Crystal Wards surrounding the Sun's Reach Sanctum to the east.", completion = "Good work, {name}.  The wards are slowly regaining their power.  The sanctum will be ours in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[11497] = { id = 11497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning to Fly", description = "Though it may end up hurting my business in the long run, you look the sort that dreams of flying <his/her> own mount through the skies, rather than being flown from place to place.\n\nI understand the feeling completely.\n\nYou, my friend, need to head to Wildhammer Stronghold in the southwest corner of Shadowmoon Valley. When you get there, speak with Ilsa Blusterbrew about some flight instruction. Mind you, her training's not cheap. But, I think that you'll find it worth your while.", sourceObjective = "Speak with Ilsa Blusterbrew at Wildhammer Stronghold in Shadowmoon Valley.", completion = "So, me boyo, Nutral, sent ya along did he?  Good man... I'll need ta remember ta send him along a pint fer all o' the business he's sendin' me way.\n\nIf it's the learnin' o' how ta fly right and proper yer after, ye've come ta the right place. No one flies finer than us Wildhammer and those we train. Fer a fee, and not a small one mind ya, I'll teach ya how ta soar through the skies!\n\nAnd when yer done, don't forget ta talk ta Brunn over there about buying one o' these gryphon beauties!", sourceObjectiveStatus = "unverified-source-field" }
quests[11498] = { id = 11498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning to Fly", description = "Though it may end up hurting my business in the long run, you look the sort that dreams of flying <his/her> own mount through the skies, rather than being flown from place to place.\n\nI understand the feeling completely.\n\nYou, my friend, need to head to Shadowmoon Village in the northwest corner of Shadowmoon Valley. When you get there, speak with Olrokk about some flight instruction. Mind you, his training's not cheap. But, I think that you'll find it worth your while.", sourceObjective = "Speak with Olrokk at Shadowmoon Village in Shadowmoon Valley.", completion = "Blood and thunder, Nutral sent me another ground grunt! Good man... for a draenei.\n\n<Olrokk spits on the ground near your feet.>\n\nYou've come to the right place if you want to learn how to ride your own mount through the skies. In return for a big sack of gold, I'll teach you what you need to know and not fall dishonorably to your death.\n\nAnd when you're done, don't forget to talk to Dama Wildmane over there about buying one of the windriders from our stable!", sourceObjectiveStatus = "unverified-source-field" }
quests[11499] = { id = 11499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: The Signet Ring of Prince Kael'thas", description = "{class}, today I ask the impossible. Today, you must obtain the signet ring of Kael'thas Sunstrider, lord of the blood elves!\n\nIt's true, the rumors of his death within Tempest Keep were ill-founded. He has appeared once more, this time at the Magisters' Terrace on the Isle of Quel'Danas. What he is doing there is a tale for someone else to tell you. What I know is that I have innumerable collectors interested in his princely ring, and I mean to acquire it for them.\n\nOr rather, I mean for you to do so.", sourceObjective = "Wind Trader Zhareem has asked you to obtain The Signet Ring of Prince Kael'thas. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed at the Magisters' Terrace on Heroic difficulty.", progress = "The Magisters' Terrace must be a very dangerous place indeed being so close to the Sunwell.\n\nI trust that you're not having second thoughts?", completion = "So, the blood elf prince is truly dead this time? A pity, I always thought he had class. To think that one so lofty could be brought down for such a paltry sum.\n\nBut as they say, business is business. Your reward is earned, adventurer.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11500] = { id = 11500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Sisters of Torment", description = "It has been whispered to Mah'duun that the sisters of torment are to be sent back to the hells from which they sprang.\n\nMah'duun knows that these demons can be found at the Magisters' Terrace on the Isle of Quel'Danas.\n\nYou will do this thing to earn the bounty, or you will not.", sourceObjective = "Nether-Stalker Mah'duun wants you to slay 4 Sisters of Torment. Return to him in Shattrath's Lower City once you have done so in order to collect the bounty.", completion = "Who can say why the demonic sisters needed to be slain? Do you care?\n\nMah'duun thinks you care enough to collect the bounty, though.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11501] = { id = 11501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News From the East", description = "Westguard needs to know what's going on here, {name}. I want you to personally deliver the news to Captain Adams.\n\nWhenever you're ready, let me know and I'll put you back in the construct for one final flight. It'll take you to Westguard Keep, but more than likely blow up in the process.\n\nIt's been a pleasure...", sourceObjective = "Speak with Captain Adams at Westguard Keep.", completion = "Wonderful... As if having the Scourge all up our you-know-whats wasn't enough, now we got some angry ancient titan construct to deal with!\n\nI'll need some time to chew on this information, {race}. In the meantime there's plenty of work that needs doing here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11502] = { id = 11502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Defense of Halaa", description = "We are not a warlike race, {race}.  However when war comes to our lands, we do not run away from it.\n\nThe Alliance and the Horde wage war in the city of Halaa, to the northwest. We do not know what the blood elves are scheming, but any victory for the Horde would be disastrous.  The history between our people and the orcs is one of bloodshed and betrayal.\n\nGo and slay the enemy in Halaa and you will be rewarded in coin, honor and renown.", sourceObjective = "Defeat 10 enemy players in Halaa and return to Lakoor in Telaar.", completion = "I thank you, {name}.  Your efforts will not be ignored.", sourceObjectiveStatus = "unverified-source-field" }
quests[11503] = { id = 11503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies, Old and New", description = "Our ancient enemy, the draenei, have returned with powerful allies.  They wage war in Halaa, southwest of here.\n\nWe cannot allow them a victory there as Garadar would be next without a doubt.\n\nGo and slay those who would aid our ancient enemy.", sourceObjective = "Defeat 10 enemy players in Halaa and return to Karrtog in Garadar.", completion = "You bring great honor to our people.  You have our thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[11504] = { id = 11504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dead Rise!", description = "The path east of us is a primary hunting trail of the tuskarr. At least that's what it used to be...\n\nMore recently our hunters have been returning to Kamagua claiming that the dead have risen and are out for blood! That is what has brought my son and me here. Elder Atuik asks that we find resolution in the bluffs.\n\nWill you assist us in our time of need? I seek heroes willing to brave the perils of Shield Hill, southeast of here. Search the desecrated graves for clues and return your findings to me.", sourceObjective = "Orfus of Kamagua at the Ancient Lift in the Howling Fjord wants you to find Fengir's Clue, Rodin's Clue, Isuldof's Clue and Windan's Clue.", progress = "The tuskarr need your help!", completion = "<Orfus's whiskers bristle.>\n\nPirates... Is there no end to the depths of their depravity?\n\nWe must recover the stolen artifacts and return them to this cursed place so that my people may once more know peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[11505] = { id = 11505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits of Auchindoun", description = "Auchindoun's spirits have no stake in the conflict between the Alliance and the Horde, but incurring their favor will give our side an edge in the region.\n\nAncient custom directs the living to pay their respects at spirit towers in the Bone Wastes - though only at specific times of the day.  If you can help secure a tower during these times, you will have helped bring the spirits to our side.\n\nShould we succeed in gaining the spirits' favor, they will grant us a boon that will aid us in our endeavors.", sourceObjective = "Help the Alliance secure a tower in the Bone Wastes.", progress = "The spirits are restless, {name}.  Have you accomplished your task?", completion = "The spirits are one step closer to resting in peace.  It is good to incur their favor, especially when waging war so close to their place of rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[11506] = { id = 11506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits of Auchindoun", description = "The draenei might be our enemies, but the spirits of their ancestors in Auchindoun are restless and have no allegiance.\n\nThe draenei's custom required them to pay their respects at spirit towers at various times during the day.  If you can help secure a tower during these times, you will help the spirits return to peace in Auchindoun.\n\nThe Alliance will try to capture the towers in order to secure the dead's favor.   We must ensure that our side succeeds instead.", sourceObjective = "Help the Horde secure a Spirit Tower in the Bone Wastes.", progress = "The spirits of Auchindoun are all around us.  Will they grant us their boon?", completion = "The spirits are closer to finding peace and have bestowed their favor onto us.\n\nA humiliating blow to our enemy that their own ancestors would side against them, even if only temporarily.", sourceObjectiveStatus = "unverified-source-field" }
quests[11507] = { id = 11507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elder Atuik and Kamagua", description = "<Orfus bundles up the clues you brought him.>\n\nMy people are bitterly entrenched in a war with the Northsea Freebooters. If any tuskarr could help us in our quest to right the wrongs of the pirates, it will be Elder Atuik of Kamagua. You must take these clues to him at once.\n\nTo get to Kamagua you must take the Ancient Lift, behind me. Take the lift directly to Kamagua and find Elder Atuik.", sourceObjective = "Orfus of Kamagua in the Howling Fjord wants you to deliver Orfus's Bundle to Elder Atuik at Kamagua.", progress = "News from Orfus?", completion = "Orfus is a good tuskarr - one of our strongest warriors. I knew he would not let us down.\n\nAllow me to see what it is that you have brought.", sourceObjectiveStatus = "unverified-source-field" }
quests[11508] = { id = 11508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grezzix Spindlesnap", description = "The pirate thieves have set up port at Scalawag Point, far to the south. Unfortunately, they have fortified their camp with many deadly defenses.\n\nThere is someone that might be able to assist us in infiltrating Scalawag.\n\nA pirate mercenary by the name of Grezzix Spindlesnap recently came to our village in search of food and shelter. In exchange he gives us information about our enemies and feeds them misinformation about our attack plans. Seek him out at his ship just off the coast here - southwest.", sourceObjective = "Speak with Grezzix Spindlesnap.", completion = "Yarr, matey. Grezzix never did like to get his hands dirty! A pirate's life for Grezzix is a good one, so long as Grezzix doesn't have to do any of the work.\n\nI've seen those artifacts. It's the reason I'm here and not at Scalawag myself! Bad, bad things those are...\n\nHey, it's your life though, right? You wanna get inside Scalawag and Grezzix can help.", sourceObjectiveStatus = "unverified-source-field" }
quests[11509] = { id = 11509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Street \"Cred\"", description = "The Northsea Freebooters all fear and respect Grezzix. I'm thinking they recognize my special talents and envy my amazing ship. All you need to do is tag along with my cabin boy, Lou, and you'll be in like... In like tin. Pirates love tin.\n\nJust talk to Lou when you're ready to go and he'll take you to Scalawag.\n\nOh yea, you'll want to talk to \"Silvermoon\" Harry first. He'll have more information on the stuff they pilfered. Just watch what you say around him. He's a freak... crazy for blood elves.", sourceObjective = "Speak with \"Silvermoon\" Harry at Scalawag Point about the missing Vrykul artifacts.", completion = "<Harry raises an eyebrow at you.>\n\nSo you're like me, eh? A little eccentric.\n\n<Harry whispers.>\n\nNobody dresses like that around here.\n\nAbout those artifacts... Everyone that came into contact with that stuff has ended up dead, missing or both.\n\nIf you're still interested in learning more, I can help - but it'll cost you.\n\n<Harry winks.>\n\nYou scratch my back and I'll try to not stick a dagger in yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[11510] = { id = 11510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Scoodles\"", description = "One of the first things Jonah Sterling did after he went crazy was to take my prized sin'dorei scrying crystal and feed it to the bane of my existence, \"Scoodles\" the orca.\n\nNo I didn't name the damned thing. I just know that she swims out past the ships directly southeast of Scalawag. Kill that overinflated goldfish and rip out my beautiful sin'dorei crystal from its stomach.\n\nDo this and we can get down to business.", sourceObjective = "\"Silvermoon\" Harry at Scalawag Point wants you to recover his Sin'dorei Scrying Crystal from the orca, \"Scoodles.\"", progress = "Are you lost?", completion = "<Harry takes the crystal from you and gently pets it.>\n\nOh my precious! Did the big, mean whale hurt you? It'll be ok. I'll never let you out of my sight again!\n\n<Harry looks up at you.>\n\nSo, where were we?", sourceObjectiveStatus = "unverified-source-field" }
quests[11511] = { id = 11511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Staff of Storm's Fury", description = "Those artifacts are cursed and you'd be crazy to go looking for them, {race}. I know for certain that anyone that's come into direct contact with any of those items has either gone mad or been killed.\n\nTake that staff, for example. Last I heard the ship that held it was abandoned and left to rot on the coast of the Isle of Spears, north of here.\n\nIf you want that thing, check the ship's hold.\n\nWhatever you do, don't bring that staff back here! And steer clear of Abdul! He'll tear your heart out.", sourceObjective = "Recover the Staff of Storm's Fury and deliver it to Orfus of Kamagua in the Howling Fjord.", progress = "You have the staff?", completion = "We must return all of the artifacts, {name}. When all four are gathered, you will put them back in their graves.", sourceObjectiveStatus = "unverified-source-field" }
quests[11512] = { id = 11512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Frozen Heart of Isuldof", description = "Some say Jonah was never quite right in the head, but I know the truth. It was the heart. That damned frozen heart! I saw the change in him the second he pulled it from the grave. I could see the blood freeze in his veins... It was then that the madness truly took over.\n\nHe left us to hole up in his cave on the north side of this island. Last I heard he had thrown the heart in the back of his bear den. Too little, too late...\n\nI'll kill you myself if you even think about bringing that heart back here!", sourceObjective = "Recover the Frozen Heart of Isuldof and deliver it to Orfus of Kamagua in the Howling Fjord.", progress = "The... The Frozen Heart of Isuldof?", completion = "We must return all of the artifacts, {name}. When all four are gathered, you will put them back in their graves.", sourceObjectiveStatus = "unverified-source-field" }
quests[11513] = { id = 11513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intercepting the Mana Cells", description = "I have devised a plan to acquire a power source strong enough for the creation of our portal.\n\nThe ethereal forces at Bash'ir Landing, atop the northwestern Blade's Edge Mountains, have been smuggling mana cells out of Tempest Keep and transporting them to the Sunwell for Kael'thas.\n\nThey have hidden the cells, but there is a way for you to find them; the ethereal carry phase devices that you can use to see the smuggled goods.\n\nJust beware the mana cells' phase wyrm guardians.", sourceObjective = "Obtain 10 Smuggled Mana Cells and return them to Exarch Nasuun on the Terrace of Light in Shattrath City.", progress = "Did you acquire the mana cells?", completion = "These mana cells are vital to our efforts. We will have the portal to the Sunwell Isle created in no time!\n\nReturn tomorrow and I will send you out to acquire more of them from our Bash'ir 'friends'.", sourceObjectiveStatus = "unverified-source-field" }
quests[11514] = { id = 11514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maintaining the Sunwell Portal", description = "We must maintain the energy to our portal or it will collapse. The mana cells that the ethereals at Bash'ir Landing have hidden will continue to serve our purposes. The landing sits atop the northwestern corner of the Blade's Edge Mountains, far to the north.\n\nRemember, acquire a phase device from one of the ethereals and then use it to locate the smuggled goods.\n\nJust be cautious of the phase wyrms that they use to guard the mana cells.", sourceObjective = "Obtain 10 Smuggled Mana Cells and return them to Exarch Nasuun on the Terrace of Light in Shattrath City.", progress = "{name}, how fare your efforts to obtain mana cells for us this day?", completion = "These mana cells will continue to power the portal.\n\nReturn tomorrow and I will send you out to obtain more.", sourceObjectiveStatus = "unverified-source-field" }
quests[11515] = { id = 11515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood for Blood", description = "When Kael's forces retreated through that portal, his most loyal lackeys were rewarded with an abominable gift.  They  stayed behind and gorged themselves on the blood of demons for days.\n\nThe blood has changed them, given them new powers.  It will also prove their undoing.\n\nObtain blood samples from other demons.  Use them to power this fel siphon and deprive these arrogant fools of their new powers.  Slay them in their weakened state and return to me.", sourceObjective = "Magistrix Seyla at the Throne of Kil'jaeden wants you to kill 4 Emaciated Felbloods by using the Fel Siphon on them. You will need Demonic Blood from nearby Wrath Heralds to power the Fel Siphon.", progress = "These freaks are a disgrace to our race.  You must destroy them, {name}.", completion = "Fools.  They learned to drain fel energy but did not learn how to retain it.\n\nWe were lucky, {name}.  An experienced felblood would've surely been a formidable opponent.", sourceObjectiveStatus = "unverified-source-field" }
quests[11516] = { id = 11516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blast the Gateway", description = "We have to shut down this gateway to stop Legion reinforcements to the Isle of Quel'Danas.\n\nTake these embers, they contain one of my creations: a living flare.  It is designed to act as a powerful destructive force - as long as it has been provided enough energy.\n\nFind the fel sparks that wander the area and slay them near the living flare.  The flare will grow in power each time, until it becomes unstable.\n\nOnce you've achieved this bring the flare to the gateway.  It will know what to do.", sourceObjective = "Magistrix Seyla at the Throne of Kil'jaeden wants you to use the Sizzling Embers to summon a Living Flare and slay Incandescent Fel Sparks near it until it becomes an Unstable Living Flare. Return to the Legion Gateway with the Unstable Living Flare to destroy it.", progress = "Is it done, {name}?  We must stop further Legion forces from reinforcing Kael'thas.", completion = "Excellent work, {name}.  The demons might repair the gateway in due time.  I suppose we'll just have to blow it up again.", sourceObjectiveStatus = "unverified-source-field" }
quests[11517] = { id = 11517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Nasuun", description = "I am most glad that you are here, {class}! Now that we have taken this sanctum, we must hurry to create a magical portal that will lead to here from Shattrath City in the Outland.\n\nMy liege lord, Exarch Nasuun, is heading up the Offensive's efforts to do just that. He asked me to send along any promising candidates who have what it takes to help with the portal's creation.\n\nPlease, travel to Shattrath City and speak with him inside A'dal's chamber on the Terrace of Light.", sourceObjective = "Tradesman Portanuus has asked you to speak with Exarch Nasuun on the Terrace of Light in Shattrath City.", completion = "Portanuus sent you? Good, we haven't any time to spare!", sourceObjectiveStatus = "unverified-source-field" }
quests[11519] = { id = 11519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Shield of the Aesirites", description = "If you listen real close you can hear cannon fire coming from the northeast. That's Captain Ellis's ship, Sister Mercy. Thing is, Ellis and his entire crew were killed 'bout a month ago.\n\n<Harry nods.>\n\nGhost ship...\n\nIf it's info you be wantin' 'bout the shield, Ellis is the man to ask.\n\nSister Mercy docks on the small island between here and Sorlof's Strand to pick up more souls for the ship's crew 'bout once every five minutes. There be no shortage of souls 'round these parts...", sourceObjective = "Speak with Captain Ellis aboard the Sister Mercy.", completion = "Arrr, me'n'me crew pilfered that thar shield! We be tryin' to get her back from that no good, landlubbin' scallywag, Sorlof! Ye come to help, arrr?\n\nWell, as ye can see we be runnin' a skeleton crew!\n\n<Captain Ellis laughs.>\n\nSister Mercy be needin' another powder monkey to man the big'uns o'er on the poop deck. Think ye be up to the job, me hearty?\n\nHelp me crew take Sorlof down and we'll split the booty! Ye can have the shield, me'n'me crew gets the rest!", sourceObjectiveStatus = "unverified-source-field" }
quests[11520] = { id = 11520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discovering Your Roots", description = "Greetings, {race}.\n\nI'm afraid I have little to offer here until my reagents are stocked.\n\nOf the supplies I require, there is a special reagent, razorthorn root, that is particularly difficult to harvest.\n\nFortunately, I know a secret....\n\nUsing the glands of the Razorthorn flayers, one can control a ravager there and use it to expose a root.\n\nTo find the roots, travel to Outlands and fly northeast from Shattrath until you reach Razorthorn Rise.", sourceObjective = "Mar'nah at Sun's Reach Harbor wants you to travel to Razorthorn Rise in Outlands, collect 5 Razorthorn Roots, and return to her.", progress = "Really, {name}, I'm far too busy for idle chatter.\n\nLet me know when you've gathered those roots.", completion = "These should do nicely, {class}.\n\nI thank you for your assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[11521] = { id = 11521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rediscovering Your Roots", description = "My stocks are presently sufficient, but I'll need plenty of razorthorn roots to keep up with the demand.\n\nCollecting the roots is difficult, but I know a special method of extraction.\n\nUsing the glands of the Razorthorn flayers, one can control a ravager there and use it to expose a root.\n\nTo find the roots, travel to Outlands and fly northeast from Shattrath until you reach Razorthorn Rise.\n\nReturn to me, {name}, once you have collected five of the roots.", sourceObjective = "Mar'nah at Sun's Reach Harbor wants you to travel to Razorthorn Rise in Outlands, collect 5 Razorthorn Roots, and return to her.", progress = "Really, {name}, I'm far too busy for idle chatter.\n\nLet me know when you've gathered those roots.", completion = "Excellent work, {name}.\n\nThank you again for your help!", sourceObjectiveStatus = "unverified-source-field" }
quests[11523] = { id = 11523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arm the Wards!", description = "We've succeeded in reactivating the crystal wards around the sanctum, but why stop there?  We'll build defenses around the other structures, but the Wretched are stubborn and continue to steal power from the crystal wards.\n\nHunt them down and get the mana remnants they carry.  Use the remnants to energize the sanctum wards; the safety of our operation depends on it.", sourceObjective = "Captain Theris Dawnhearth at the Shattered Sun Staging Area wants you to obtain 4 Mana Remnants from Wretched Fiends and Wretched Devourers and use them to energize one of the Crystal Wards surrounding the structures in Sun's Reach.", progress = "Have you reactivated a crystal ward, {name}?", completion = "Good work, {name}.  The wards are slowly regaining their power.  Sun's Reach will be ours in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[11524] = { id = 11524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erratic Behavior", description = "We lack the numbers to capture the Sanctum at Sun's Reach, but I've a plan that will tip the scales in our favor.\n\nThe loose energy from the Sunwell has caused the sentries that patrol this island to malfunction.  The crystal cores that control their behavior are damaged beyond repair.\n\nI've crafted new crystals that will bring them under our control; place them inside of the hulls of defeated sentries.  We will need all the help we can get.", sourceObjective = "Vindicator Xayanna at the Shattered Sun Staging Area wants you to place the Attuned Crystal Cores inside 5 defeated Erratic Sentries to turn them into friendly units.", progress = "Have you converted the sentries, {name}?", completion = "Good job, {name}.  The sanctum will be ours in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[11525] = { id = 11525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Further Conversions", description = "My plan to replace the damaged crystals on the erratic sentries has been a success.  We've managed to take the Sun's Reach Sanctum with their help.\n\nI've crafted new crystals that will bring more of them under our control; place them inside the hulls of defeated sentries.  We'll deploy them to other locations once they're converted.", sourceObjective = "Vindicator Xayann at the Shattered Sun Staging Area wants you to place the Attuned Crystal Cores inside 5 defeated Erratic Sentries to turn them into friendly units.", progress = "Have you converted the sentries, {name}?", completion = "Excellent.  The converted sentries will help to secure our perimeter.", sourceObjectiveStatus = "unverified-source-field" }
quests[11526] = { id = 11526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Magistrix", description = "We sent one of our operatives to investigate the fel portal in the middle of Dawning Square, south of here.  She never returned.\n\nTake this scroll we found on one of the enemy corpses.  We believe it will grant you access through the portal.  Once through, find Magistrix Seyla and aid her in any way you can.", sourceObjective = "Use the Captured Legion Scroll near the portal at Dawning Square. Once you've gone through the portal, find Magistrix Seyla.", progress = "Keep quiet, {class}.  The Legion's forces watch the south of the gate.", completion = "It's very sweet of Theris to worry about my hide, but we've got bigger problems here.  Much bigger.", sourceObjectiveStatus = "unverified-source-field" }
quests[11527] = { id = 11527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mutiny on the Mercy", description = "Aye, we got problems, matey. Me gunners have mutinied! M'n'the crew up top be tryin' to kick Sorlof's keester while dealin' with the mutinous gunners down'blo.\n\nYe're gonna have to go down'blo and deal with those mutinous sea dogs and take their blastin' powder for the big'un o'er on the poop deck.\n\nWith ye mannin' the big'un, Sorlof is sure to die and give up the booty!", sourceObjective = "Captain Ellis aboard the Sister Mercy in the Howling Fjord has asked that you recover 5 Barrels of Blasting Powder from the ship's hold.", progress = "Mutinous sea dogs and giants abound!", completion = "Here's to hopin' those treacherous bilge rats learned their lessons! Now it be time to man the big'un, matey!", sourceObjectiveStatus = "unverified-source-field" }
quests[11528] = { id = 11528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Winter Veil Gift", sourceObjective = "A small tag on this present reads:\n\nHappy holidays, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11529] = { id = 11529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sorlof's Booty", description = "Me crew is gonna get the big'un all primed an'ready for ya, matey. She's restin' snuggly on the bow, o'er on the other side of the ship. Go'n man it and be ready to fire when Sorlof is in our sights!\n\nOnce we take that landlubber down, ye'll have to recover the booty for us, seein' as how we can't leave the damned ship! Bring that booty back to me and ye'll get your cut - the shield...", sourceObjective = "Slay Sorlof using the Big Gun and recover Sorlof's Booty. Return Sorlof's Booty to Captain Ellis aboard the Sister Mercy.", progress = "Smartly, me hearty!", completion = "A deal's a deal, me hearty!", sourceObjectiveStatus = "unverified-source-field" }
quests[11530] = { id = 11530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shield of the Aesirites", description = "Here's yer shield. Me hopes it doesn't curse ye like it did me'n'me crew. Ye don't have to go home, but ye can't stay here... I be certain that thar be some that would be interested in getting' it back.\n\nNow get that thing off me ship!", sourceObjective = "Return the Shield of the Aesirites to Orfus of Kamagua at the Ancient Lift in the Howling Fjord.", progress = "You have returned!", completion = "We must return all of the artifacts, {name}. When all four are gathered, you will put them back in their graves.", sourceObjectiveStatus = "unverified-source-field" }
quests[11531] = { id = 11531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Engine Part", description = "This strange engine part doesn't look like it fits in a steam pump, much less anything else you've seen.  Perhaps K. Lee Smallfry might know something about it.", sourceObjective = "Take the Strange Engine Part to K. Lee Smallfry in Telredor.", progress = "Oh goodness!  What've you got there, {name}?", completion = "<K. Lee looks at the engine part and then stares off into the distance for a moment.>\n\nThis is somethin' real special.  Difficulty to say where it's from--like it just fell out of the sky.  I'm gonna hold on to this and pay you for your troubles.\n\nBetween you and me though, I think it's best if we didn't mention this to anyone.\n\n<K. Lee puts on her most charming smile.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11532] = { id = 11532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distraction at the Dead Scar", description = "The Legion will move against us as soon as their forces to the south are freed up.  The Scourge at the Dead Scar are keeping their forces occupied at the moment.  It won't last long, however.\n\nI want you to fly a dragonhawk over to the scar and put a dent in the demons' numbers with these arcane charges.\n\nIf all goes well, they won't even notice us taking the armory from Kael's lackeys.  Talk to Ayren, the dragonhawk master in the west part of the harbor, when you're ready to fly there.", sourceObjective = "Battlemage Arynna wants you to speak to Ayren Cloudbreaker when you're ready to fly over the Dead Scar. Once there, use the Arcane Charges to kill 2 Pit Overlords, 3 Eredar Sorcerers and 12 Wrath Enforcers.", progress = "Have you accomplished your mission, {name}?", completion = "You've got some real talent, kid.  Did you ever think of joining the Skyguard?\n\nI jest, {name}.  We need you here if we want to take the docks any time soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[11533] = { id = 11533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Air Strikes Must Continue", description = "We've taken the armory from the enemy thanks to our aerial attacks against the Legion's forces in the Dead Scar.\n\nAs a matter of fact, it's gone so well that we're going to continue our air strikes against them.  Take these arcane charges and use them against their forces.\n\nTalk to Ayren Cloudbreaker at the Sun's Reach Harbor when you're ready for flight.", sourceObjective = "Battlemage Arynna wants you to speak to Ayren Cloudbreaker when you're ready to fly over the Dead Scar. Once there, use the Arcane Charges to kill 2 Pit Overlords, 3 Eredar Sorcerers and 12 Wrath Enforcers.", progress = "Have you accomplished your mission, {name}?", completion = "Any demons we kill today are demons that we do not have to fight tomorrow.  Keep it up.", sourceObjectiveStatus = "unverified-source-field" }
quests[11534] = { id = 11534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Nasuun", description = "I am most glad that you are here, {class}! When we took this sanctum from the wretched, we hurried to create a magical portal that leads here from Shattrath City in the Outland.\n\nMy liege lord, Exarch Nasuun, is heading up the Offensive's efforts to maintain that portal. He asked me to send along any promising candidates who have what it takes to help with acquiring more energy to fuel it.\n\nPlease, travel to Shattrath City and speak with him inside A'dal's chamber on the Terrace of Light.", sourceObjective = "Tradesman Portanuus has asked you to speak with Exarch Nasuun on the Terrace of Light in Shattrath City.", completion = "Portanuus sent you? Good, we haven't any time to spare!", sourceObjectiveStatus = "unverified-source-field" }
quests[11535] = { id = 11535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Ready", description = "Supplies are inbound, or so I'm told.\n\nRegardless, we can ill afford to wait around hoping that help arrives before our offensive stalls. We must make the best of what we have.\n\nAs for me, I need ore to fashion an anvil so I can begin to upgrade our armor and weapons.\n\nThere are a group of naga on the coast to the east of here collecting ore and placing it in chests for shipment to the Legion.\n\nRelieving them of their ore will help our efforts in more ways than one....", sourceObjective = "Smith Hauthaa in Sun's Reach Armory wants you to kill Darkspine Myrmidon to the east and use their keys to steal three pieces of the ore from their chests.", progress = "Have you gathered the ore I need?", completion = "Excellent! We're getting closer....\n\nSoon I'll be able to craft an anvil, then the real work can begin.", sourceObjectiveStatus = "unverified-source-field" }
quests[11536] = { id = 11536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Stop Now....", description = "Now that we have an anvil, I can really get to work.\n\nNo matter how many supplies we receive, I'll always be able to put the Darkspine Iron Ore to good use. We'll need a constant supply of weapons and armor if we're to be successful here.\n\nThere are a group of naga on the coast to the east of here. They're collecting ore and placing it in chests for shipment to the Legion. Relieving them of their ore will help our efforts in more ways than one....", sourceObjective = "Smith Hauthaa in Sun's Reach Armory wants you to kill Darkspine Myrmidon to the east and use their keys to steal three pieces of the ore from their chests.", progress = "Have you gathered the ore I asked for?", completion = "Excellent! This will help me keep our soldiers in weapons and armor.\n\nYour help is truly making a difference!", sourceObjectiveStatus = "unverified-source-field" }
quests[11537] = { id = 11537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle Must Go On", description = "We must continue to defeat and demoralize the armies of the Legion.\n\nThe emissaries of hate are Legion shocktroopers deployed to reinforce tactical Legion positions.  The enemy rallies around them for they fear them more than they fear us.\n\nToday we will change that.  Take this banner and slay the demons of the Legion.  When you meet the emissary, slay and impale him.", sourceObjective = "Harbinger Inuuro wants you to slay 6 Burning Legion Demons and the Emissary of Hate in Dawning Square. Use the Shattered Sun Banner to impale the Emissary of Hate's corpse.", progress = "Have you succeeded, {name}?", completion = "Your dedication is exemplary, {name}.  We will show the forces of the Burning Legion what we're capable of.", sourceObjectiveStatus = "unverified-source-field" }
quests[11538] = { id = 11538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for the Sun's Reach Armory", description = "The Burning Legion holds the Sun's Reach Armory, which is of tactical importance to our operation.  As long as their morale remains high we will not wrest the building from their control.\n\nThe emissaries of hate are Legion shocktroopers deployed to reinforce tactical Legion positions.  The enemy rallies around them for they fear them more than they fear us.\n\nToday we will change that.  Take this banner and slay the demons of the Legion.  When you meet the emissary, slay and impale him.", sourceObjective = "Harbinger Inuuro wants you to slay 6 Burning Legion Demons and the Emissary of Hate in Dawning Square or the Sun's Reach Armory. Use the Shattered Sun Banner to impale the Emissary of Hate's corpse.", progress = "Have you done what I asked of you, {name}?", completion = "Your dedication is exemplary, {name}.  We will take the armory from the forces of the Legion in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[11539] = { id = 11539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Harbor", description = "One of Kael's most elite forces, the Dawnblade army, has been stationed at the Sun's Reach Harbor and Dawnstar Village.\n\nThe harbor is of critical importance to our plans, so any Dawnblade casualties you inflict will be of tremendous help.  Kael'thas will rue the day that he turned his back on his people and sided with the Burning Legion.", sourceObjective = "Magister Ilastar at Sun's Reach Armory wants you to slay 6 Dawnblade Summoners, 6 Dawnblade Blood Knights and 3 Dawnblade Marksmen.", completion = "Excellent work, {class}.  Kael's armies will falter and once we take the harbor we shall deliver the killing blow!", sourceObjectiveStatus = "unverified-source-field" }
